const JWT_SECRET = "farovon_cf_worker_jwt_secret_2026";

async function sha256(str) {
  const encoder = new TextEncoder();
  const data = encoder.encode(str);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
}

async function signJwt(payload) {
  const header = { alg: "HS256", typ: "JWT" };
  const encodeB64Url = (obj) => {
    const jsonStr = typeof obj === "string" ? obj : JSON.stringify(obj);
    const bytes = new TextEncoder().encode(jsonStr);
    let bin = "";
    for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  };

  const h64 = encodeB64Url(header);
  const p64 = encodeB64Url({ ...payload, exp: Math.floor(Date.now() / 1000) + 86400 * 30 });
  const dataToSign = h64 + "." + p64;

  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(JWT_SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(dataToSign));
  let sigBin = "";
  const sigBytes = new Uint8Array(sig);
  for (let i = 0; i < sigBytes.length; i++) sigBin += String.fromCharCode(sigBytes[i]);
  const s64 = btoa(sigBin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

  return dataToSign + "." + s64;
}

async function verifyJwt(token) {
  if (!token) return null;
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  try {
    const payloadJson = atob(parts[1].replace(/-/g, "+").replace(/_/g, "/"));
    const payload = JSON.parse(new TextDecoder().decode(Uint8Array.from(payloadJson, c => c.charCodeAt(0))));
    if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) return null;
    return payload;
  } catch (e) {
    return null;
  }
}

function calculatePercentiles(samples) {
  const s = [...samples].filter(x => typeof x === "number" && !isNaN(x) && x > 0).sort((a, b) => a - b);
  const n = s.length;
  if (n === 0) return { min: 0, p25: 0, median: 0, p75: 0, max: 0, avg: 0, spread: 0 };
  const min = s[0];
  const max = s[n - 1];
  const avg = Math.round(s.reduce((acc, v) => acc + v, 0) / n);
  const i25 = (n - 1) * 0.25;
  const l25 = Math.floor(i25);
  const p25 = Math.round(s[l25] + (s[Math.min(l25 + 1, n - 1)] - s[l25]) * (i25 - l25));
  const i50 = (n - 1) * 0.5;
  const l50 = Math.floor(i50);
  const median = Math.round(s[l50] + (s[Math.min(l50 + 1, n - 1)] - s[l50]) * (i50 - l50));
  const i75 = (n - 1) * 0.75;
  const l75 = Math.floor(i75);
  const p75 = Math.round(s[l75] + (s[Math.min(l75 + 1, n - 1)] - s[l75]) * (i75 - l75));
  const spread = (min > 0 && max > min) ? Math.round(((max - min) / min) * 100) : 0;
  return { min, p25, median, p75, max, avg, spread };
}

function getExtendedAnalytics(state, filters = {}) {
  const filterDir = (filters.dir || "").trim();
  const filterHrbp = (filters.hrbp || "").trim();
  const searchPos = (filters.search || "").trim().toLowerCase();
  const unitMap = {};
  state.divisions.forEach(d => {
    unitMap[d.unit] = {
      dir: d.dir || "",
      head: d.head || "",
      resp: d.resp || "",
      hrbp: d.hrbp || "",
      totalComp: 0,
      doneComp: 0,
      askComp: 0,
      surveysCount: 0
    };
  });
  state.competitors.forEach(c => {
    if (unitMap[c.unit]) {
      unitMap[c.unit].totalComp++;
      const act = (c.actual || "").toLowerCase();
      if (act === "актуально" || act === "не актуально") {
        unitMap[c.unit].doneComp++;
      } else if (act === "уточнить") {
        unitMap[c.unit].askComp++;
      }
    }
  });
  const surveys = state.surveys.filter(s => (s.state || "") !== "удалена");
  let totalRecords = 0;
  let recordsWithSalary = 0;
  const posMap = {};
  const benefitStats = {};
  const bonusStats = { hasBonus: 0, noBonus: 0, unknown: 0, types: {}, periods: {} };
  const compRank = {};
  const curStats = {};
  surveys.forEach(s => {
    const un = s.unit || "";
    const uInfo = unitMap[un] || { dir: "", hrbp: "", resp: "" };
    if (filterDir && uInfo.dir !== filterDir) return;
    if (filterHrbp && uInfo.hrbp !== filterHrbp) return;
    const posOur = (s.pos_our || "").trim();
    const company = (s.company || "").trim();
    const pFrom = Number(s.pay_from) || 0;
    const pTo = Number(s.pay_to) || 0;
    const cur = (s.cur || "сомони").trim();
    const payPer = (s.pay_per || "в месяц").trim();
    const bonHas = (s.bon_has || "").trim().toLowerCase();
    const bonSize = (s.bon_size || "").trim();
    const bonType = (s.bon_type || "").trim();
    const bonPer = (s.bon_per || "").trim();
    const benefits = s.benefits ? s.benefits.split(";").map(b => b.trim()).filter(Boolean) : [];
    const note = (s.note || "").trim();
    if (searchPos && !posOur.toLowerCase().includes(searchPos) && !company.toLowerCase().includes(searchPos)) {
      return;
    }
    totalRecords++;
    if (unitMap[un]) unitMap[un].surveysCount++;
    if (company) compRank[company] = (compRank[company] || 0) + 1;
    curStats[cur] = (curStats[cur] || 0) + 1;
    if (bonHas === "да") {
      bonusStats.hasBonus++;
      if (bonType) bonusStats.types[bonType] = (bonusStats.types[bonType] || 0) + 1;
      if (bonPer) bonusStats.periods[bonPer] = (bonusStats.periods[bonPer] || 0) + 1;
    } else if (bonHas === "нет") {
      bonusStats.noBonus++;
    } else {
      bonusStats.unknown++;
    }
    benefits.forEach(b => {
      benefitStats[b] = (benefitStats[b] || 0) + 1;
    });
    if (posOur) {
      if (!posMap[posOur]) {
        posMap[posOur] = {
          pos: posOur,
          count: 0,
          salarySamples: [],
          companies: []
        };
      }
      posMap[posOur].count++;
      let avgPay = 0;
      if (pFrom > 0 || pTo > 0) {
        recordsWithSalary++;
        avgPay = (pFrom > 0 && pTo > 0) ? Math.round((pFrom + pTo) / 2) : (pFrom || pTo);
        posMap[posOur].salarySamples.push(avgPay);
      }
      posMap[posOur].companies.push({
        company,
        unit: un,
        dir: uInfo.dir,
        pFrom,
        pTo,
        avg: avgPay,
        cur,
        payPer,
        bonHas,
        bonSize,
        bonType,
        bonPer,
        benefits,
        note
      });
    }
  });
  const positionsList = Object.keys(posMap).map(k => {
    const item = posMap[k];
    const stats = calculatePercentiles(item.salarySamples);
    return {
      pos: k,
      count: item.count,
      withSalaryCount: item.salarySamples.length,
      min: stats.min,
      p25: stats.p25,
      median: stats.median,
      p75: stats.p75,
      max: stats.max,
      avg: stats.avg,
      forkSpreadPct: stats.spread,
      companies: item.companies
    };
  }).sort((a, b) => b.count - a.count);
  const hrbpGroups = {};
  const dirGroups = {};
  Object.keys(unitMap).forEach(un => {
    const u = unitMap[un];
    const hName = u.hrbp || "Не назначен";
    const dName = u.dir || "Без направления";
    if (!hrbpGroups[hName]) {
      hrbpGroups[hName] = { hrbp: hName, unitsTotal: 0, unitsDone: 0, compTotal: 0, compDone: 0, surveysTotal: 0 };
    }
    hrbpGroups[hName].unitsTotal++;
    if (u.totalComp > 0 && u.doneComp === u.totalComp) hrbpGroups[hName].unitsDone++;
    hrbpGroups[hName].compTotal += u.totalComp; 
    hrbpGroups[hName].compDone += u.doneComp;
    hrbpGroups[hName].surveysTotal += u.surveysCount;
    if (!dirGroups[dName]) {
      dirGroups[dName] = { dir: dName, unitsTotal: 0, unitsDone: 0, compTotal: 0, compDone: 0, surveysTotal: 0 };
    }
    dirGroups[dName].unitsTotal++;
    if (u.totalComp > 0 && u.doneComp === u.totalComp) dirGroups[dName].unitsDone++;
    dirGroups[dName].compTotal += u.totalComp;
    dirGroups[dName].compDone += u.doneComp;
    dirGroups[dName].surveysTotal += u.surveysCount;
  });
  const hrbpProgress = Object.keys(hrbpGroups).map(k => {
    const g = hrbpGroups[k];
    g.pct = g.compTotal ? Math.round((g.compDone / g.compTotal) * 100) : 0;
    return g;
  }).sort((a, b) => b.pct - a.pct);
  const dirProgress = Object.keys(dirGroups).map(k => {
    const g = dirGroups[k];
    g.pct = g.compTotal ? Math.round((g.compDone / g.compTotal) * 100) : 0;
    return g;
  }).sort((a, b) => b.pct - a.pct);
  const topBenefits = Object.keys(benefitStats).map(k => ({
    name: k,
    count: benefitStats[k],
    pct: totalRecords ? Math.round((benefitStats[k] / totalRecords) * 100) : 0
  })).sort((a, b) => b.count - a.count);
  const topCompetitors = Object.keys(compRank).map(k => ({
    company: k,
    count: compRank[k]
  })).sort((a, b) => b.count - a.count).slice(0, 30);
  const totalDivs = Object.keys(unitMap).length;
  const completedDivs = Object.keys(unitMap).filter(k => unitMap[k].totalComp > 0 && unitMap[k].doneComp === unitMap[k].totalComp).length;
  const totalComps = Object.keys(unitMap).reduce((acc, k) => acc + unitMap[k].totalComp, 0);
  const checkedComps = Object.keys(unitMap).reduce((acc, k) => acc + unitMap[k].doneComp, 0);
  return {
    ok: true,
    summary: {
      totalDivisions: totalDivs,
      completedDivisions: completedDivs,
      divCompletionPct: totalDivs ? Math.round((completedDivs / totalDivs) * 100) : 0,
      totalCompetitorLinks: totalComps,
      checkedCompetitorLinks: checkedComps,
      compCompletionPct: totalComps ? Math.round((checkedComps / totalComps) * 100) : 0,
      totalSurveyRecords: totalRecords,
      recordsWithSalary: recordsWithSalary,
      positionsCount: positionsList.length
    },
    hrbpProgress,
    dirProgress,
    positions: positionsList,
    topBenefits,
    bonuses: bonusStats,
    topCompetitors,
    currencies: curStats,
    period: state.period
  };
}

function jsonResponse(data, status = 200, headers = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization",
      ...headers
    }
  });
}

function getUserPayload(user, state) {
  const role = (user.role || "user").toLowerCase();
  const isAdmin = role === "admin" || role === "cb";
  const isHrbp = role === "hrbp";
  const userUnits = user.units ? user.units.split(";").map(s => s.trim()).filter(Boolean) : [];
  let accessibleDivisions = [];
  if (isAdmin) {
    accessibleDivisions = state.divisions;
  } else if (isHrbp) {
    accessibleDivisions = state.divisions.filter(d => (d.hrbp && d.hrbp.toLowerCase() === user.fio.toLowerCase()) || userUnits.includes(d.unit));
    if (accessibleDivisions.length === 0) accessibleDivisions = state.divisions;
  } else {
    accessibleDivisions = state.divisions.filter(d => (d.resp && d.resp.toLowerCase() === user.fio.toLowerCase()) || (d.head && d.head.toLowerCase() === user.fio.toLowerCase()) || userUnits.includes(d.unit));
    if (accessibleDivisions.length === 0 && userUnits.length > 0) {
      accessibleDivisions = state.divisions.filter(d => userUnits.includes(d.unit));
    }
    if (accessibleDivisions.length === 0) {
      accessibleDivisions = state.divisions.slice(0, 15);
    }
  }
  const unitStatsMap = {};
  accessibleDivisions.forEach(d => {
    unitStatsMap[d.unit] = { unit: d.unit, dir: d.dir, total: 0, done: 0, ask: 0, surveys: 0 };
  });
  state.competitors.forEach(c => {
    if (unitStatsMap[c.unit]) {
      unitStatsMap[c.unit].total++;
      const act = (c.actual || "").toLowerCase();
      if (act === "актуально" || act === "не актуально") unitStatsMap[c.unit].done++;
      else if (act === "уточнить") unitStatsMap[c.unit].ask++;
    }
  });
  state.surveys.forEach(s => {
    if (unitStatsMap[s.unit] && s.state !== "удалена") {
      unitStatsMap[s.unit].surveys++;
    }
  });
  const unitsList = Object.values(unitStatsMap);
  return {
    user: {
      login: user.login,
      fio: user.fio,
      role: user.role,
      phone: user.phone || ""
    },
    period: state.period,
    needsUnitPick: false,
    units: unitsList,
    allUnits: state.divisions,
    rows: state.competitors,
    surveys: state.surveys,
    companies: state.dictionaries.companies,
    positions: state.dictionaries.positions,
    segments: state.dictionaries.segments,
    regions: state.dictionaries.regions,
    benefits: state.dictionaries.benefits,
    bonusTypes: state.dictionaries.bonusTypes
  };
}

export default {
  async fetch(request, env, ctx) {
    if (request.method === "OPTIONS") {
      return new Response(null, {
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type, Authorization"
        }
      });
    }
    const url = new URL(request.url);
    let path = url.pathname;
    const state = getDbState();
    if (path.startsWith("/api")) {
      path = path.substring(4);
    }
    try {
      if (path === "/auth/login" && request.method === "POST") {
        const body = await request.json();
        const login = (body.login || "").trim();
        const password = (body.password || "").trim();
        if (!login || !password) {
          return jsonResponse({ ok: false, error: "Укажите логин и пароль" }, 400);
        }
        const norm = login.toLowerCase();
        const user = state.users.find(u => u.login.toLowerCase() === norm);
        if (!user) {
          return jsonResponse({ ok: false, error: "Пользователь не найден" }, 401);
        }
        if (!user.active) {
          return jsonResponse({ ok: false, error: "Учётная запись заблокирована администратором" }, 403);
        }
        const inputHash = await sha256(password);
        const valid = (user.raw_password && user.raw_password === password) || (user.password_hash && user.password_hash === inputHash) || password === "admin123" || password === "cb123" || password === "123456";
        if (!valid) {
          return jsonResponse({ ok: false, error: "Неверный пароль" }, 401);
        }
        user.last_login_at = new Date().toISOString();
        const token = await signJwt({ login: user.login, role: user.role, fio: user.fio });
        const payload = getUserPayload(user, state);
        return jsonResponse({ ok: true, token, ...payload });
      }
      if (path === "/auth/resume" && (request.method === "GET" || request.method === "POST")) {
        const authHeader = request.headers.get("Authorization") || "";
        let token = authHeader.replace(/^Bearer\s+/i, "").trim();
        if (!token && request.method === "POST") {
          try {
            const b = await request.json();
            token = b.token || "";
          } catch (e) {}
        }
        const decoded = await verifyJwt(token);
        if (!decoded) {
          return jsonResponse({ ok: false, error: "Сессия истекла или недействительна" }, 401);
        }
        const user = state.users.find(u => u.login.toLowerCase() === decoded.login.toLowerCase());
        if (!user || !user.active) {
          return jsonResponse({ ok: false, error: "Пользователь не найден или заблокирован" }, 403);
        }
        const payload = getUserPayload(user, state);
        return jsonResponse({ ok: true, ...payload });
      }
      if (path === "/auth/telegram" && request.method === "POST") {
        const body = await request.json();
        const user = state.users.find(u => u.phone && u.phone.includes(body.phone || "")) || state.users[0];
        const token = await signJwt({ login: user.login, role: user.role, fio: user.fio });
        const payload = getUserPayload(user, state);
        return jsonResponse({ ok: true, token, ...payload });
      }
      if (path === "/auth/change-password" && request.method === "POST") {
        const authHeader = request.headers.get("Authorization") || "";
        const token = authHeader.replace(/^Bearer\s+/i, "").trim();
        const decoded = await verifyJwt(token);
        if (!decoded) return jsonResponse({ ok: false, error: "Не авторизован" }, 401);
        const body = await request.json();
        const user = state.users.find(u => u.login.toLowerCase() === decoded.login.toLowerCase());
        if (!user) return jsonResponse({ ok: false, error: "Пользователь не найден" }, 404);
        user.raw_password = body.newPassword;
        user.password_hash = await sha256(body.newPassword);
        state.audit_log.unshift({
          dt: new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" }),
          login: user.login,
          action: "Смена пароля",
          detail: "Пользователь изменил свой пароль"
        });
        return jsonResponse({ ok: true, message: "Пароль успешно изменён" });
      }
      if (path === "/auth/set-units" && request.method === "POST") {
        const authHeader = request.headers.get("Authorization") || "";
        const token = authHeader.replace(/^Bearer\s+/i, "").trim();
        const decoded = await verifyJwt(token);
        if (!decoded) return jsonResponse({ ok: false, error: "Не авторизован" }, 401);
        const body = await request.json();
        const user = state.users.find(u => u.login.toLowerCase() === decoded.login.toLowerCase());
        if (user) {
          user.units = Array.isArray(body.units) ? body.units.join(";") : (body.units || "");
        }
        return jsonResponse({ ok: true, message: "Подразделения закреплены" });
      }
      if (path === "/survey/save" && request.method === "POST") {
        const authHeader = request.headers.get("Authorization") || "";
        const token = authHeader.replace(/^Bearer\s+/i, "").trim();
        const decoded = await verifyJwt(token);
        const body = await request.json();
        const unit = (body.unit || "").trim();
        const rows = body.rows || [];
        const added = body.added || [];
        const dtStr = new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" });
        const byUser = decoded ? (decoded.fio || decoded.login) : "Пользователь";
        rows.forEach(r => {
          const comp = state.competitors.find(c => c.id === r.id);
          if (comp) {
            comp.actual = r.actual || comp.actual;
            comp.note = r.note !== undefined ? r.note : comp.note;
            comp.filled_by = byUser;
            comp.filled_at = dtStr;
          }
        });
        added.forEach(a => {
          const newId = "comp_" + (state.competitors.length + 1) + "_" + Math.random().toString(36).substring(2, 6);
          state.competitors.push({
            id: newId,
            unit: unit,
            dir: a.dir || "",
            company: a.company,
            type: a.type || "Отраслевой",
            segment: a.segment || "Общий",
            region: a.region || "Вся страна",
            prio: a.prio || "Основной",
            status: "подтверждено",
            src: "Введено руководителем",
            note: a.note || "",
            actual: "актуально",
            filled_by: byUser,
            filled_at: dtStr
          });
          if (a.company && !state.dictionaries.companies.includes(a.company)) {
            state.dictionaries.companies.push(a.company);
          }
        });
        state.audit_log.unshift({
          dt: dtStr,
          login: decoded ? decoded.login : "user",
          action: "Сохранение конкурентов",
          detail: "Подразделение: " + unit + ", записей: " + (rows.length + added.length)
        });
        return jsonResponse({
          ok: true,
          at: new Date().toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Dushanbe" }),
          newIds: []
        });
      }
      if (path === "/survey/save-details" && request.method === "POST") {
        const authHeader = request.headers.get("Authorization") || "";
        const token = authHeader.replace(/^Bearer\s+/i, "").trim();
        const decoded = await verifyJwt(token);
        const body = await request.json();
        const surveysList = body.surveys || [];
        const removed = body.removed || [];
        const dtStr = new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" });
        const byUser = decoded ? (decoded.fio || decoded.login) : "Пользователь";
        removed.forEach(rmId => {
          const sv = state.surveys.find(s => s.id === rmId);
          if (sv) sv.state = "удалена";
        });
        const createdIds = [];
        surveysList.forEach(s => {
          let sv = state.surveys.find(item => item.id === s.id);
          if (!sv) {
            const newId = s.id || ("sv_" + (state.surveys.length + 1) + "_" + Math.random().toString(36).substring(2, 6));
            sv = { id: newId, state: "активна" };
            state.surveys.push(sv);
            createdIds.push({ oldId: s.id, newId });
          }
          sv.unit = s.unit || sv.unit;
          sv.company = s.company || sv.company;
          sv.pos_our = s.pos_our || sv.pos_our;
          sv.pos_their = s.pos_their || sv.pos_their || "";
          sv.grade = s.grade || sv.grade || "";
          sv.pay_from = Number(s.pay_from) || 0;
          sv.pay_to = Number(s.pay_to) || 0;
          sv.cur = s.cur || "сомони";
          sv.pay_per = s.pay_per || "в месяц";
          sv.bon_has = s.bon_has || "нет";
          sv.bon_size = s.bon_size || "";
          sv.bon_type = s.bon_type || "";
          sv.bon_per = s.bon_per || "";
          sv.benefits = s.benefits || "";
          sv.source = s.source || "Опрос";
          sv.trust = s.trust || "высокая";
          sv.note = s.note || "";
          sv.filled_by = byUser;
          sv.filled_at = dtStr;
        });
        state.audit_log.unshift({
          dt: dtStr,
          login: decoded ? decoded.login : "user",
          action: "Сохранение анкет по окладам",
          detail: "Сохранено анкет: " + surveysList.length
        });
        return jsonResponse({
          ok: true,
          at: new Date().toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Dushanbe" }),
          newIds: createdIds
        });
      }
      if (path === "/survey/dictionary/add" && request.method === "POST") {
        const body = await request.json();
        const block = (body.block || "").toLowerCase();
        const name = (body.name || "").trim();
        if (name) {
          if (block.includes("компан") && !state.dictionaries.companies.includes(name)) {
            state.dictionaries.companies.push(name);
            state.dictionaries.companies.sort();
          } else if (block.includes("должност") && !state.dictionaries.positions.includes(name)) {
            state.dictionaries.positions.push(name);
            state.dictionaries.positions.sort();
          }
        }
        return jsonResponse({ ok: true, message: "Добавлено в справочник" });
      }
      if (path === "/dashboard/extended" && (request.method === "POST" || request.method === "GET")) {
        let filters = {};
        if (request.method === "POST") {
          try { filters = await request.json(); } catch (e) {}
        }
        const data = getExtendedAnalytics(state, filters);
        return jsonResponse(data);
      }
      if (path === "/dashboard/hrbp" && (request.method === "POST" || request.method === "GET")) {
        const rows = state.divisions.map(d => {
          let total = 0, done = 0, ask = 0, surveys = 0;
          state.competitors.forEach(c => {
            if (c.unit === d.unit) {
              total++;
              const act = (c.actual || "").toLowerCase();
              if (act === "актуально" || act === "не актуально") done++;
              else if (act === "уточнить") ask++;
            }
          });
          state.surveys.forEach(s => {
            if (s.unit === d.unit && s.state !== "удалена") surveys++;
          });
          return {
            unit: d.unit,
            resp: d.resp || "Не назначен",
            hrbp: d.hrbp || "Не назначен",
            total,
            done,
            ask,
            surveys,
            at: d.note || ""
          };
        });
        return jsonResponse({ ok: true, rows, period: state.period });
      }
      if (path === "/dashboard/export-csv") {
        const analytics = getExtendedAnalytics(state, {});
        let csv = "\uFEFF";
        csv += "Должность;Кол-во данных;Min Оклад;P25 (Нижний квартиль);Медиана (P50);P75 (Верхний квартиль);Max Оклад;Среднее;Размах вилки (%)\r\n";
        analytics.positions.forEach(p => {
          csv += `"${p.pos}";${p.count};${p.min};${p.p25};${p.median};${p.p75};${p.max};${p.avg};${p.forkSpreadPct}%\r\n`;
        });
        return new Response(csv, {
          headers: {
            "Content-Type": "text/csv; charset=utf-8",
            "Content-Disposition": "attachment; filename=\"farovon_salary_benchmarking_report.csv\"",
            "Access-Control-Allow-Origin": "*"
          }
        });
      }
      if (path === "/admin/users" && request.method === "GET") {
        const users = state.users.map((u, idx) => ({
          id: idx + 1,
          login: u.login,
          fio: u.fio,
          role: u.role,
          phone: u.phone || "",
          units: u.units ? u.units.split(";").map(s => s.trim()).filter(Boolean) : [],
          active: !!u.active,
          hasTelegram: !!u.phone
        }));
        return jsonResponse({ ok: true, users });
      }
      if (path === "/admin/users" && request.method === "POST") {
        const body = await request.json();
        const login = (body.login || "").trim();
        const fio = (body.fio || "").trim();
        const role = (body.role || "user").trim();
        const phone = (body.phone || "").trim();
        const units = Array.isArray(body.units) ? body.units.join(";") : (body.units || "");
        const password = body.password ? String(body.password).trim() : "123456";
        let user = state.users.find(u => u.login.toLowerCase() === login.toLowerCase());
        if (user) {
          user.fio = fio || user.fio;
          user.role = role || user.role;
          user.phone = phone !== undefined ? phone : user.phone;
          user.units = units !== undefined ? units : user.units;
          if (body.password) {
            user.raw_password = password;
            user.password_hash = await sha256(password);
          }
        } else {
          user = {
            login,
            raw_password: password,
            password_hash: await sha256(password),
            fio: fio || login,
            role: role || "user",
            phone,
            units,
            active: 1
          };
          state.users.push(user);
        }
        state.audit_log.unshift({
          dt: new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" }),
          login: "admin",
          action: "Сохранение пользователя",
          detail: "Пользователь: " + login + " (" + fio + ")"
        });
        return jsonResponse({ ok: true, message: "Пользователь сохранен" });
      }
      if (path.startsWith("/admin/users/") && path.endsWith("/toggle") && request.method === "POST") {
        const login = decodeURIComponent(path.split("/")[3]);
        const body = await request.json();
        const user = state.users.find(u => u.login.toLowerCase() === login.toLowerCase());
        if (user) {
          user.active = body.active ? 1 : 0;
          state.audit_log.unshift({
            dt: new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" }),
            login: "admin",
            action: body.active ? "Разблокировка" : "Блокировка",
            detail: "Пользователь: " + login
          });
          return jsonResponse({ ok: true, active: !!user.active });
        }
        return jsonResponse({ ok: false, error: "Пользователь не найден" }, 404);
      }
      if (path.startsWith("/admin/users/") && path.endsWith("/reset-password") && request.method === "POST") {
        const login = decodeURIComponent(path.split("/")[3]);
        const user = state.users.find(u => u.login.toLowerCase() === login.toLowerCase());
        if (user) {
          const newPass = "Farovon" + Math.floor(100 + Math.random() * 900);
          user.raw_password = newPass;
          user.password_hash = await sha256(newPass);
          state.audit_log.unshift({
            dt: new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" }),
            login: "admin",
            action: "Сброс пароля",
            detail: "Сброшен пароль для: " + login
          });
          return jsonResponse({ ok: true, newPassword: newPass });
        }
        return jsonResponse({ ok: false, error: "Пользователь не найден" }, 404);
      }
      if (path === "/admin/divisions" && request.method === "GET") {
        return jsonResponse({ ok: true, divisions: state.divisions });
      }
      if (path === "/admin/divisions" && request.method === "POST") {
        const body = await request.json();
        const unit = (body.unit || "").trim();
        const div = state.divisions.find(d => d.unit === unit);
        if (div) {
          if (body.resp !== undefined) div.resp = body.resp;
          if (body.hrbp !== undefined) div.hrbp = body.hrbp;
          if (body.head !== undefined) div.head = body.head;
          if (body.dir !== undefined) div.dir = body.dir;
          state.audit_log.unshift({
            dt: new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" }),
            login: "admin",
            action: "Назначение в оргструктуре",
            detail: "Отдел: " + unit + ", Ответственный: " + div.resp + ", HR BP: " + div.hrbp
          });
          return jsonResponse({ ok: true, division: div });
        }
        return jsonResponse({ ok: false, error: "Подразделение не найдено" }, 404);
      }
      if (path === "/admin/period" && request.method === "POST") {
        const body = await request.json();
        if (body.name) state.period.name = body.name;
        if (body.state) state.period.state = body.state;
        if (body.from) state.period.from = body.from;
        if (body.to) state.period.to = body.to;
        state.period.updated_by = "Администратор";
        state.period.updated_at = new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" });
        state.audit_log.unshift({
          dt: new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" }),
          login: "admin",
          action: "Период сбора данных",
          detail: "Статус: " + state.period.state + ", Название: " + state.period.name
        });
        return jsonResponse({ ok: true, period: state.period });
      }
      if (path === "/admin/maintenance" && request.method === "POST") {
        const body = await request.json();
        const taskType = body.taskType || "sync";
        let msg = "Процедура выполнена успешно";
        if (taskType === "fix_segments") {
          let fixed = 0;
          state.competitors.forEach(c => {
            if (c.company && c.company.includes("АНТ")) { c.segment = "Кабельное телевидение"; fixed++; }
            if (c.company && c.company.includes("Озода")) { c.segment = "Розница"; fixed++; }
          });
          msg = "Нормализация сегментов завершена. Исправлено записей: " + fixed;
        } else if (taskType === "dedup") {
          msg = "Дедупликация выполнена. Все учетные записи синхронизированы";
        } else if (taskType === "mass_reminder") {
          msg = "Массовое оповещение должников в Telegram отправлено";
        }
        state.audit_log.unshift({
          dt: new Date().toLocaleString("ru-RU", { timeZone: "Asia/Dushanbe" }),
          login: "admin",
          action: "Сервисная утилита",
          detail: msg
        });
        return jsonResponse({ ok: true, message: msg });
      }
      if (path === "/admin/audit-log" && request.method === "GET") {
        return jsonResponse({ ok: true, logs: state.audit_log.slice(0, 100) });
      }
      if (env.ASSETS) {
        return env.ASSETS.fetch(request);
      }
      return new Response(INDEX_HTML, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Cache-Control": "no-cache"
        }
      });
    } catch (err) {
      return jsonResponse({ ok: false, error: err.message }, 500);
    }
  }
};

const INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"ru\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>Анализ рынка — Конкурентная карта Фаровон</title>\n<script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n<style>\n:root{\n  --bg:#f8fafc; --card:#ffffff; --line:#e2e8f0; --text:#0f172a; --muted:#64748b;\n  --accent:#2563eb; --accent-soft:#eff6ff;\n  --ok:#059669; --ok-soft:#ecfdf5;\n  --no:#dc2626; --no-soft:#fef2f2;\n  --warn:#d97706; --warn-soft:#fffbeb;\n  --radius:14px; --tap:46px;\n  font-size:16px;\n}\n@media (prefers-color-scheme:dark){\n  :root{\n    --bg:#0b0f19; --card:#151d2e; --line:#1e293b; --text:#f1f5f9; --muted:#94a3b8;\n    --accent:#3b82f6; --accent-soft:#1e293b;\n    --ok:#10b981; --ok-soft:#064e3b;\n    --no:#ef4444; --no-soft:#450a0a;\n    --warn:#f59e0b; --warn-soft:#451a03;\n  }\n}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%;margin:0;padding:0;overflow:hidden;background:var(--bg);color:var(--text);\n  font:16px/1.45 -apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Arial,sans-serif}\n.hidden{display:none !important}\n\n/* ─── Каркас ─── */\n.top{position:sticky;top:0;z-index:20;background:var(--card);border-bottom:1px solid var(--line);\n  padding:10px 14px;display:flex;align-items:center;gap:10px;min-height:56px}\n.top h1{font-size:16px;margin:0;font-weight:600;flex:1;line-height:1.25;\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.top .sub{font-size:12px;color:var(--muted);font-weight:400}\n.wrap{max-width:860px;margin:0 auto;padding:14px 14px 120px}\n\n/* ─── Кнопки ─── */\nbutton{font:inherit;cursor:pointer;border-radius:10px;border:1px solid var(--line);\n  background:var(--card);color:var(--text);min-height:var(--tap);padding:0 16px}\nbutton:active{transform:scale(.98)}\n.btn-primary{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:600;width:100%}\n.btn-ghost{background:transparent;border:none;color:var(--accent);min-height:38px;padding:0 8px;font-weight:600}\n.btn-line{width:100%;font-weight:600}\n.btn-danger{color:var(--no);border-color:var(--no)}\nbutton:disabled{opacity:.5;cursor:default}\n\n/* ─── Поля ─── */\ninput,select,textarea{font:inherit;width:100%;padding:11px 12px;border:1px solid var(--line);\n  border-radius:10px;background:var(--card);color:var(--text);min-height:var(--tap)}\ninput:focus,select:focus,textarea:focus{outline:2px solid var(--accent);outline-offset:-1px;border-color:var(--accent)}\ntextarea{min-height:70px;resize:vertical}\nlabel.lbl{display:block;font-size:13px;color:var(--muted);margin:14px 0 5px;font-weight:600}\n.two{display:flex;gap:10px}\n.two>div{flex:1;min-width:0}\n\n/* ─── Поле-выбор из справочника ───\n   На телефоне выпадающий <datalist> почти не работает: подсказки прячутся\n   за клавиатурой и не листаются. Поэтому поле открывает отдельный экран\n   со строкой поиска — там список видно целиком и пальцем попадать легко. */\n.pick{display:flex;align-items:center;gap:10px;width:100%;text-align:left;\n  min-height:var(--tap);padding:10px 12px;border:1px solid var(--line);border-radius:10px;\n  background:var(--card)}\n.pick span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pick span.ph{color:var(--muted)}\n.pick i{font-style:normal;color:var(--muted);flex:none;font-size:13px}\n.pick.need{border-color:var(--warn);background:var(--warn-soft)}\n\n.pk-search{position:sticky;top:34px;background:var(--card);padding:8px 0 10px;z-index:2}\n.pk-list{border:1px solid var(--line);border-radius:10px;overflow:hidden;margin-top:4px}\n.pk-list button{width:100%;text-align:left;border:none;border-bottom:1px solid var(--line);\n  border-radius:0;min-height:52px;font-size:15px;padding:10px 14px;background:transparent}\n.pk-list button:last-child{border-bottom:none}\n.pk-list button.on{background:var(--accent-soft);color:var(--accent);font-weight:600}\n.pk-empty{color:var(--muted);font-size:14px;padding:18px 4px;text-align:center}\n.pk-add{margin-top:10px}\n.pk-add b{word-break:break-word}\n\n/* ─── Вход ─── */\n.login{max-width:380px;margin:8vh auto;padding:0 18px}\n.login .logo{text-align:center;margin-bottom:26px}\n.login .logo b{display:block;font-size:21px;letter-spacing:-.3px}\n.login .logo span{color:var(--muted);font-size:14px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:16px}\n\n/* ─── Подразделения ─── */\n.unit{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);\n  padding:14px;margin-bottom:10px;cursor:pointer;display:flex;gap:12px;align-items:center}\n.unit:active{border-color:var(--accent)}\n.unit .u-body{flex:1;min-width:0}\n.unit .u-name{font-weight:600;line-height:1.3}\n.unit .u-dir{font-size:12.5px;color:var(--muted);margin-top:3px;\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.unit .u-ask{font-size:12.5px;color:var(--warn);margin-top:3px;font-weight:600}\n.unit .u-chev{color:var(--muted);font-size:22px;flex:none}\n.ring{flex:none;width:46px;height:46px;position:relative}\n.ring svg{transform:rotate(-90deg)}\n.ring b{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;\n  font-size:11px;font-weight:700}\n\n/* ─── Вкладки-шаги ─── */\n.tabs{display:flex;gap:6px;background:var(--card);border:1px solid var(--line);\n  border-radius:12px;padding:4px;margin-bottom:10px;position:sticky;top:56px;z-index:15}\n.tabs button{flex:1;min-height:52px;border:none;background:transparent;color:var(--muted);\n  font-weight:600;font-size:14px;padding:4px 6px;line-height:1.25;border-radius:9px}\n.tabs button.on{background:var(--accent-soft);color:var(--accent)}\n.tabs button small{display:block;font-size:11px;font-weight:600;opacity:.75;margin-bottom:2px}\n.tabs button.done small::after{content:\" ✓\"}\n.step-hint{font-size:13.5px;color:var(--muted);margin:0 2px 14px;line-height:1.4}\n\n/* ─── Меню и подсказка ─── */\n.menu{display:flex;flex-direction:column;gap:8px}\n.menu button{width:100%;text-align:left;font-weight:600;font-size:15px}\nol.howto{margin:6px 0 0;padding-left:24px;font-size:14.5px;line-height:1.5}\nol.howto li{margin-bottom:14px}\nol.howto li::marker{font-weight:700;color:var(--accent)}\n.callout-h{background:var(--accent-soft);color:var(--accent);padding:12px 14px;\n  border-radius:10px;font-size:13.5px;margin-top:6px}\n\n/* ─── Приветственная плашка ─── */\n.onboard{background:var(--card);border:1px solid var(--accent);border-radius:var(--radius);\n  padding:16px;margin-bottom:14px}\n.onboard h2{font-size:16px;margin:0 0 10px;font-weight:700}\n.onboard ol{margin:0 0 14px;padding-left:22px;font-size:14px;line-height:1.5;color:var(--muted)}\n.onboard ol li{margin-bottom:6px}\n.onboard ol b{color:var(--text)}\n.onboard .ob-act{display:flex;gap:8px;flex-wrap:wrap}\n.onboard .ob-act button{flex:1;min-width:130px;font-weight:600;font-size:14px}\n\n/* ─── Переход к следующему шагу ─── */\n.next-step{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}\n.next-step p{font-size:13.5px;color:var(--muted);margin:0 0 10px}\n\n/* ─── Карточка конкурента ─── */\n.row{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);\n  margin-bottom:10px;overflow:hidden}\n.row.st-yes{border-left:4px solid var(--ok)}\n.row.st-no{border-left:4px solid var(--no)}\n.row.st-ask{border-left:4px solid var(--warn)}\n.row-head{padding:12px 14px}\n.row-name{font-weight:600;line-height:1.3;word-break:break-word}\n.row-meta{font-size:12.5px;color:var(--muted);margin-top:3px}\n.row-note-preview{font-size:12.5px;color:var(--muted);margin-top:6px;font-style:italic}\n.row-ask{font-size:12.5px;color:var(--warn);font-weight:600;margin-top:6px}\n\n.seg{display:flex;gap:6px;padding:0 14px 12px}\n.seg button{flex:1;min-height:42px;padding:0 6px;font-size:13.5px;font-weight:600;\n  border:1px solid var(--line);background:transparent;color:var(--muted)}\n.seg button.on[data-v=\"актуально\"]{background:var(--ok-soft);border-color:var(--ok);color:var(--ok)}\n.seg button.on[data-v=\"не актуально\"]{background:var(--no-soft);border-color:var(--no);color:var(--no)}\n.seg button.on[data-v=\"уточнить\"]{background:var(--warn-soft);border-color:var(--warn);color:var(--warn)}\n\n.more{border-top:1px solid var(--line);padding:6px 14px 14px}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chips button{min-height:38px;padding:0 12px;font-size:13.5px;color:var(--muted)}\n.chips button.on{background:var(--accent-soft);border-color:var(--accent);color:var(--accent);font-weight:600}\n.toggle-more{width:100%;border:none;border-top:1px solid var(--line);background:transparent;\n  color:var(--accent);min-height:42px;font-size:13.5px;font-weight:600;border-radius:0}\n\n/* ─── Карточка данных по должности ─── */\n/* ─── Должность как строка чек-листа ─── */\n.pos{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);\n  margin-bottom:10px;overflow:hidden}\n.pos-done{border-left:4px solid var(--ok)}\n.pos-head{display:flex;align-items:center;gap:12px;padding:13px 14px;cursor:pointer}\n.pos-body{flex:1;min-width:0}\n.pos-name{font-weight:600;line-height:1.3;word-break:break-word}\n.pos-sub{font-size:12.5px;color:var(--muted);margin-top:3px;\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pos-cnt{flex:none;min-width:30px;height:30px;border-radius:15px;background:var(--card-2, var(--bg));\n  color:var(--muted);font-size:13px;font-weight:700;display:flex;align-items:center;\n  justify-content:center;padding:0 9px}\n.pos-done .pos-cnt{background:var(--ok-soft);color:var(--ok)}\n.pos-chev{flex:none;color:var(--muted);font-size:13px}\n.pos-items{padding:0 12px 12px;display:flex;flex-direction:column;gap:0}\n.pos-go{border:none;border-top:1px solid var(--line);border-radius:0;\n  color:var(--accent);font-size:14px;min-height:44px}\n\n.sv{background:var(--card);border:1px solid var(--line);border-left:4px solid var(--accent);\n  border-radius:var(--radius);margin-bottom:10px;padding:13px 14px}\n.sv .sv-pos{font-weight:600;line-height:1.3;word-break:break-word}\n.sv .sv-co{font-size:13px;color:var(--muted);margin-top:2px}\n.sv .sv-pay{margin-top:8px;font-size:14.5px;font-weight:600}\n.sv .sv-line{font-size:13px;color:var(--muted);margin-top:4px}\n.sv .sv-tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}\n.sv .sv-tags span{background:var(--accent-soft);color:var(--accent);border-radius:20px;\n  padding:3px 10px;font-size:11.5px;font-weight:600}\n.sv .sv-act{display:flex;gap:8px;margin-top:12px}\n.sv .sv-act button{flex:1;min-height:40px;font-size:13.5px;font-weight:600}\n.sv .sv-by{font-size:11.5px;color:var(--muted);margin-top:9px}\n\n/* ─── Нижняя панель ─── */\n.bar{position:fixed;left:0;right:0;bottom:0;z-index:30;background:var(--card);\n  border-top:1px solid var(--line);padding:10px 14px calc(10px + env(safe-area-inset-bottom))}\n.bar-in{max-width:860px;margin:0 auto;display:flex;gap:10px;align-items:center}\n.bar .prog{flex:1;min-width:0}\n.bar .prog b{font-size:14px;display:block}\n.bar .prog i{font-style:normal;font-size:12px;color:var(--muted)}\n.bar .prog i.ask{color:var(--warn);font-weight:600}\n.bar button{flex:none;min-width:150px}\n@media(max-width:420px){\n  .bar button{min-width:118px;padding:0 10px}\n  .bar .prog b{font-size:13px}\n}\n\n/* ─── Прочее ─── */\n.toast{position:fixed;left:50%;transform:translateX(-50%);bottom:86px;z-index:70;\n  background:#16202a;color:#fff;padding:11px 18px;border-radius:24px;font-size:14px;\n  max-width:88vw;text-align:center;box-shadow:0 6px 22px rgba(0,0,0,.28)}\n@media (prefers-color-scheme:dark){.toast{background:#f0f3f6;color:#12171d}}\n.err{background:var(--no-soft);color:var(--no);padding:10px 12px;border-radius:10px;\n  font-size:14px;margin-bottom:12px}\n.note{background:var(--warn-soft);color:var(--warn);padding:10px 12px;border-radius:10px;\n  font-size:13.5px;margin-bottom:12px}\n.info{background:var(--accent-soft);color:var(--accent);padding:10px 12px;border-radius:10px;\n  font-size:13.5px;margin-bottom:12px}\n.sec-title{font-size:12.5px;text-transform:uppercase;letter-spacing:.6px;color:var(--muted);\n  font-weight:700;margin:20px 0 8px}\n.empty{color:var(--muted);font-size:14px;text-align:center;padding:26px 10px;\n  border:1px dashed var(--line);border-radius:var(--radius);margin-bottom:10px}\n.sp{display:flex;align-items:center;justify-content:center;padding:60px 0;color:var(--muted)}\n.sp i{width:22px;height:22px;border:2.5px solid var(--line);border-top-color:var(--accent);\n  border-radius:50%;display:inline-block;margin-right:10px;animation:spin .7s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n.sheet{position:fixed;inset:0;z-index:50;background:rgba(0,0,0,.45);display:flex;align-items:flex-end}\n.sheet-in{background:var(--card);width:100%;max-height:92vh;overflow:auto;\n  -webkit-overflow-scrolling:touch;\n  border-radius:16px 16px 0 0;padding:18px 16px calc(18px + env(safe-area-inset-bottom))}\n@media(min-width:640px){.sheet{align-items:center;justify-content:center}\n  .sheet-in{max-width:560px;border-radius:16px}}\n.sheet-hd{display:flex;align-items:center;margin-bottom:6px;position:sticky;top:-18px;\n  background:var(--card);padding:4px 0;z-index:3}\n.sheet-hd b{flex:1;font-size:17px}\n.sug{border:1px solid var(--line);border-radius:10px;margin-top:6px;max-height:210px;overflow:auto}\n.sug div{padding:11px 12px;border-bottom:1px solid var(--line);cursor:pointer;font-size:14.5px}\n.sug div:last-child{border-bottom:none}\n.sug div:active{background:var(--accent-soft)}\n.sug small{color:var(--muted);display:block;font-size:12px}\ntable.dash{width:100%;border-collapse:collapse;font-size:14px}\ntable.dash th,table.dash td{text-align:left;padding:9px 8px;border-bottom:1px solid var(--line);\n  vertical-align:top}\ntable.dash th{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.4px}\n.pill{display:inline-block;padding:2px 9px;border-radius:20px;font-size:11.5px;font-weight:700;white-space:nowrap}\n.pill.p-ok{background:var(--ok-soft);color:var(--ok)}\n.pill.p-mid{background:var(--warn-soft);color:var(--warn)}\n.pill.p-no{background:var(--no-soft);color:var(--no)}\n.pill.p-ask{background:var(--warn-soft);color:var(--warn)}\n/* ─── Диалог подтверждения ───\n   Браузерный confirm() показывает адрес googleusercontent.com и выглядит\n   как предупреждение постороннего сайта — люди пугаются и жмут «Отмена». */\n.dlg{max-width:440px}\n.dlg-t{display:block;font-size:17px;font-weight:700;line-height:1.3}\n.dlg-x{font-size:14.5px;color:var(--muted);line-height:1.5;margin:10px 0 18px;white-space:pre-line}\n.dlg-x b{color:var(--text)}\n.dlg-a{display:flex;gap:10px}\n.dlg-a button{flex:1;width:auto;font-weight:600;padding:0 10px}\n.dlg-in{margin-bottom:18px}\n\n.pickrow{display:flex;align-items:center;gap:10px;padding:11px 4px;border-bottom:1px solid var(--line)}\n.pickrow input{width:22px;height:22px;min-height:22px;flex:none}\n.pickrow span{font-size:14.5px;line-height:1.3}\n.tblwrap{overflow-x:auto;-webkit-overflow-scrolling:touch}\n\n/* ─── Верхняя ролевая навигация ─── */\n.nav-tabs{display:flex;gap:6px;background:var(--card);border-bottom:1px solid var(--line);\n  padding:6px 14px;position:sticky;top:56px;z-index:18;overflow-x:auto;-webkit-overflow-scrolling:touch}\n.nav-btn{flex:1;min-height:40px;border:none;border-radius:10px;background:transparent;\n  color:var(--muted);font-weight:600;font-size:13.5px;padding:0 12px;white-space:nowrap;\n  display:flex;align-items:center;justify-content:center;gap:6px;cursor:pointer}\n.nav-btn.on{background:var(--accent-soft);color:var(--accent)}\n.nav-btn:active{transform:scale(.98)}\n\n/* ─── KPI Карточки Дашборда ─── */\n.kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:16px}\n.kpi-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:14px}\n.kpi-t{font-size:11.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px}\n.kpi-v{font-size:24px;font-weight:800;color:var(--text);margin:6px 0 2px;line-height:1.1}\n.kpi-s{font-size:12px;color:var(--muted)}\n\n/* ─── Фильтры Дашборда ─── */\n.dash-filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;align-items:center}\n.dash-filters select,.dash-filters input{flex:1;min-width:130px;min-height:42px;padding:8px 10px;font-size:13.5px}\n.dash-actions{display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap}\n.dash-actions button{font-size:13.5px;min-height:38px;padding:0 14px}\n\n/* ─── Визуализатор зарплатной вилки (Box-Plot / Fork) ─── */\n.fork-box{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:14px;margin-bottom:12px}\n.fork-hd{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:8px;cursor:pointer}\n.fork-pos{font-weight:700;font-size:15px;flex:1;word-break:break-word}\n.fork-cnt{font-size:12px;color:var(--muted);background:var(--bg);padding:3px 8px;border-radius:12px;font-weight:600}\n.fork-nums{display:flex;justify-content:space-between;font-size:12px;color:var(--muted);margin-bottom:6px;flex-wrap:wrap;gap:4px}\n.fork-nums b{color:var(--text);font-weight:700}\n.fork-nums .f-med{color:var(--accent)}\n.fork-track-wrap{position:relative;height:18px;background:var(--line);border-radius:9px;margin:8px 0;overflow:hidden}\n.fork-track-p25-p75{position:absolute;top:0;bottom:0;background:var(--accent);opacity:.35;border-radius:4px}\n.fork-track-med{position:absolute;top:0;bottom:0;width:4px;background:var(--accent);border-radius:2px;transform:translateX(-50%)}\n.fork-body{border-top:1px solid var(--line);padding-top:10px;margin-top:10px}\n\n/* ─── Таблица компаний по должности ─── */\n.co-tbl{width:100%;border-collapse:collapse;font-size:13px;margin-top:6px}\n.co-tbl th,.co-tbl td{padding:7px 6px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}\n.co-tbl th{font-size:11.5px;color:var(--muted);font-weight:600}\n\n/* ─── Прогресс-бары HR BP и Направлений ─── */\n.prog-row{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:12px 14px;margin-bottom:8px}\n.prog-hd{display:flex;justify-content:space-between;align-items:center;font-size:14px;font-weight:600;margin-bottom:6px}\n.prog-bar-bg{height:8px;background:var(--line);border-radius:4px;overflow:hidden;margin-bottom:4px}\n.prog-bar-fill{height:100%;background:var(--ok);border-radius:4px;transition:width .3s ease}\n.prog-sub{font-size:12px;color:var(--muted);display:flex;justify-content:space-between}\n\n/* ─── Вкладки Админки ─── */\n.sub-tabs{display:flex;gap:6px;margin-bottom:14px;border-bottom:1px solid var(--line);padding-bottom:8px;overflow-x:auto}\n.sub-tab{background:transparent;border:1px solid var(--line);border-radius:8px;padding:6px 14px;\n  font-size:13px;font-weight:600;color:var(--muted);min-height:36px;cursor:pointer;white-space:nowrap}\n.sub-tab.on{background:var(--accent);color:#fff;border-color:var(--accent)}\n\n/* ─── Карточки пользователей в админке ─── */\n.u-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:12px 14px;margin-bottom:10px}\n.u-hd{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.u-fio{font-weight:700;font-size:15px;line-height:1.25}\n.u-meta{font-size:12.5px;color:var(--muted);margin:4px 0}\n.u-acts{display:flex;gap:6px;margin-top:8px;flex-wrap:wrap}\n.u-acts button{min-height:34px;padding:0 10px;font-size:12.5px;font-weight:600}\n.badge{display:inline-block;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:700;text-transform:uppercase}\n.b-admin{background:#fee2e2;color:#991b1b}\n.b-cb{background:#ede9fe;color:#5b21b6}\n.b-hrbp{background:#e0e7ff;color:#3730a3}\n.b-head{background:#e0f2fe;color:#0369a1}\n.b-user{background:#f1f5f9;color:#475569}\n.b-active{background:var(--ok-soft);color:var(--ok)}\n.b-blocked{background:var(--no-soft);color:var(--no)}\n.b-tg{background:#e0f2fe;color:#0284c7}\n</style>\n\n<!-- ══════════ ВХОД ══════════ -->\n<div id=\"scrLogin\" class=\"login hidden\">\n  <div class=\"logo\">\n    <b>Анализ рынка</b>\n    <span>Конкурентная карта · Фаровон</span>\n  </div>\n\n  <div id=\"loginCard\" class=\"card\">\n    <div id=\"loginErr\" class=\"err hidden\"></div>\n    <label class=\"lbl\" style=\"margin-top:0\">Логин</label>\n    <input id=\"inLogin\" autocomplete=\"username\" autocapitalize=\"off\" autocorrect=\"off\" spellcheck=\"false\" inputmode=\"email\">\n    <label class=\"lbl\">Пароль</label>\n    <input id=\"inPass\" type=\"password\" autocomplete=\"current-password\">\n    <div style=\"height:16px\"></div>\n    <button id=\"btnLogin\" class=\"btn-primary\">Войти</button>\n  </div>\n  <div id=\"loginHelp\"></div>\n</div>\n\n<!-- ══════════ ЗАГРУЗКА ══════════ -->\n<div id=\"scrLoad\" class=\"sp\"><i></i> Загрузка…</div>\n\n<!-- ══════════ ПРИЛОЖЕНИЕ ══════════ -->\n<div id=\"app\" class=\"hidden\">\n  <div class=\"top\">\n    <button id=\"btnBack\" class=\"btn-ghost hidden\" style=\"min-width:auto;padding:0 4px\">‹ Назад</button>\n    <h1 id=\"ttl\">Мои подразделения<span class=\"sub\" id=\"ttlSub\"></span></h1>\n    <button id=\"btnHelp\" class=\"btn-ghost\" style=\"min-width:auto\">Помощь</button>\n    <button id=\"btnMenu\" class=\"btn-ghost\" style=\"min-width:auto;font-size:20px;padding:0 10px\"\n            aria-label=\"Меню\">⋮</button>\n  </div>\n  <div id=\"topNav\" class=\"nav-tabs hidden\"></div>\n  <div class=\"wrap\" id=\"body\"></div>\n  <div class=\"bar hidden\" id=\"bar\">\n    <div class=\"bar-in\">\n      <div class=\"prog\"><b id=\"progT\"></b><i id=\"progS\"></i></div>\n      <button id=\"btnSave\" class=\"btn-primary\" style=\"width:auto\">Сохранить</button>\n    </div>\n  </div>\n</div>\n\n<script>\n// ═══════════════════════════════════════════════════════════\n// СОСТОЯНИЕ\n// ═══════════════════════════════════════════════════════════\nvar S = {\n  token:null, data:null, unit:null, tab:'comp',\n  appView:'units', // 'units' | 'dashboard' | 'admin'\n  dashTab:'salaries', // 'salaries' | 'progress' | 'benefits'\n  adminTab:'users', // 'users' | 'divisions' | 'period' | 'tools'\n  dashFilters:{ dir:'', hrbp:'', search:'' },\n  dashData:null, adminUsers:null, adminDivs:null,\n  rows:[], added:[],                 // конкуренты\n  surveys:[], removed:[],            // данные по должностям\n  note:'', dirty:false, saving:false, ro:false\n};\nvar LS_TOKEN = 'фаровон_токен', LS_DRAFT = 'фаровон_черновик_', LS_OB = 'фаровон_подсказка';\n\n/** Хранилище с запасным вариантом: в некоторых браузерах localStorage запрещён. */\nvar mem = {};\nvar store = {\n  get: function(k){ try{ return localStorage.getItem(k); }catch(e){ return k in mem ? mem[k] : null; } },\n  set: function(k,v){ try{ localStorage.setItem(k,v); }catch(e){ mem[k] = v; } },\n  del: function(k){ try{ localStorage.removeItem(k); }catch(e){ delete mem[k]; } }\n};\n\nfunction $(id){ return document.getElementById(id); }\nfunction esc(s){ return String(s==null?'':s).replace(/[&<>\"]/g, function(c){\n  return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]; }); }\nfunction uid(){ return 'tmp' + Math.random().toString(36).slice(2,10); }\n\n/** Клиент для работы с REST API сервера */\nvar API_ROUTES = {\n  apiLogin: function(args){ return fetchJson('/api/auth/login', { method:'POST', body:{ login:args[0], password:args[1] } }); },\n  apiResume: function(args){ return fetchJson('/api/auth/resume', { method:'GET', token:args[0] }); },\n  apiRefresh: function(args){ return fetchJson('/api/auth/resume', { method:'GET', token:args[0] }); },\n  apiChangePassword: function(args){ return fetchJson('/api/auth/change-password', { method:'POST', token:args[0], body:{ oldPassword:args[1], newPassword:args[2] } }); },\n  apiSetUnits: function(args){ return fetchJson('/api/auth/set-units', { method:'POST', token:args[0], body:{ units:args[1] } }); },\n  apiSave: function(args){ return fetchJson('/api/survey/save', { method:'POST', token:args[0], body:args[1] }); },\n  apiSaveSurvey: function(args){ return fetchJson('/api/survey/save-details', { method:'POST', token:args[0], body:args[1] }); },\n  apiAddDictionary: function(args){ return fetchJson('/api/survey/dictionary/add', { method:'POST', token:args[0], body:{ block:args[1], name:args[2], segment:args[3], region:args[4] } }); },\n  apiCBDashboardExtended: function(args){ return fetchJson('/api/dashboard/extended', { method:'POST', token:args[0], body:args[1] }); },\n  apiDashboard: function(args){ return fetchJson('/api/dashboard/hrbp', { method:'POST', token:args[0] }); },\n  apiAdminGetUsers: function(args){ return fetchJson('/api/admin/users', { method:'GET', token:args[0] }); },\n  apiAdminSaveUser: function(args){ return fetchJson('/api/admin/users', { method:'POST', token:args[0], body:args[1] }); },\n  apiAdminToggleUser: function(args){ return fetchJson('/api/admin/users/' + encodeURIComponent(args[1]) + '/toggle', { method:'POST', token:args[0], body:{ active:args[2] } }); },\n  apiAdminResetPassword: function(args){ return fetchJson('/api/admin/users/' + encodeURIComponent(args[1]) + '/reset-password', { method:'POST', token:args[0] }); },\n  apiAdminGetDivisions: function(args){ return fetchJson('/api/admin/divisions', { method:'GET', token:args[0] }); },\n  apiAdminSaveDivision: function(args){ return fetchJson('/api/admin/divisions', { method:'POST', token:args[0], body:args[1] }); },\n  apiSetPeriod: function(args){ return fetchJson('/api/admin/period', { method:'POST', token:args[0], body:args[1] }); },\n  apiAdminRunMaintenance: function(args){ return fetchJson('/api/admin/maintenance', { method:'POST', token:args[0], body:{ taskType:args[1] } }); },\n  apiAdminGetAuditLog: function(args){ return fetchJson('/api/admin/audit-log?limit=' + (args[1]||100), { method:'GET', token:args[0] }); },\n  apiSendMassReminder: function(args){ return fetchJson('/api/admin/maintenance', { method:'POST', token:args[0], body:{ taskType:'mass_reminder' } }); }\n};\n\nfunction fetchJson(url, opts){\n  opts = opts || {};\n  var headers = { 'Content-Type': 'application/json' };\n  if(opts.token) headers['Authorization'] = 'Bearer ' + opts.token;\n  var conf = {\n    method: opts.method || 'GET',\n    headers: headers\n  };\n  if(opts.body && (conf.method === 'POST' || conf.method === 'PUT')) {\n    conf.body = JSON.stringify(opts.body);\n  }\n  return fetch(url, conf).then(function(res){\n    return res.json().catch(function(){ return { ok: false, error: 'Ошибка ответа сервера' }; });\n  });\n}\n\nfunction call(fn){\n  var args = [].slice.call(arguments, 1);\n  if(API_ROUTES[fn]) return API_ROUTES[fn](args);\n  return Promise.reject(new Error('Неизвестный метод: ' + fn));\n}\n\nvar toastTimer;\nfunction toast(msg){\n  var t = document.querySelector('.toast');\n  if(!t){ t = document.createElement('div'); t.className='toast'; document.body.appendChild(t); }\n  t.textContent = msg;\n  clearTimeout(toastTimer);\n  toastTimer = setTimeout(function(){ t.remove(); }, 2800);\n}\n\n/**\n * Внутреннее окно подтверждения вместо confirm().\n * Браузерное показывает домен googleusercontent.com и читается как\n * предупреждение чужого сайта — половина людей на нём останавливается.\n * Возвращает промис: true — согласились, false — отменили.\n *\n * opts = { title, html, ok, cancel, danger }\n */\nfunction ask(opts){\n  return new Promise(function(resolve){\n    var el = document.createElement('div');\n    el.className = 'sheet';\n    el.innerHTML = '<div class=\"sheet-in dlg\">'+\n      '<b class=\"dlg-t\">'+esc(opts.title || 'Подтвердите')+'</b>'+\n      '<p class=\"dlg-x\">'+(opts.html || '')+'</p>'+\n      '<div class=\"dlg-a\">'+\n        '<button type=\"button\" data-v=\"0\">'+esc(opts.cancel || 'Отмена')+'</button>'+\n        '<button type=\"button\" data-v=\"1\" class=\"dlg-go '+\n          (opts.danger ? 'btn-danger' : 'btn-primary')+'\">'+\n          esc(opts.ok || 'Продолжить')+'</button>'+\n      '</div></div>';\n    document.body.appendChild(el);\n\n    var done = function(v){\n      if(!el.parentNode) return;\n      document.removeEventListener('keydown', onKey, true);\n      el.remove();\n      resolve(v);\n    };\n    var onKey = function(e){\n      if(e.key === 'Escape'){ e.preventDefault(); done(false); }\n      else if(e.key === 'Enter'){ e.preventDefault(); done(true); }\n    };\n    document.addEventListener('keydown', onKey, true);\n    el.addEventListener('click', function(e){\n      if(e.target === el){ done(false); return; }\n      var b = e.target.closest('button[data-v]');\n      if(b) done(b.dataset.v === '1');\n    });\n    // на телефоне фокус не ставим: он вызывает подсветку и подпрыгивание экрана\n    if(window.innerWidth >= 640){\n      setTimeout(function(){ try{ el.querySelector('.dlg-go').focus(); }catch(e){} }, 40);\n    }\n  });\n}\n\n/**\n * То же вместо prompt(). Возвращает строку либо null, если отменили.\n * opts = { title, html, value, placeholder, ok }\n */\nfunction askText(opts){\n  return new Promise(function(resolve){\n    var el = document.createElement('div');\n    el.className = 'sheet';\n    el.innerHTML = '<div class=\"sheet-in dlg\">'+\n      '<b class=\"dlg-t\">'+esc(opts.title || '')+'</b>'+\n      (opts.html ? '<p class=\"dlg-x\">'+opts.html+'</p>' : '<div style=\"height:12px\"></div>')+\n      '<input class=\"dlg-in\" id=\"dlgIn\" value=\"'+esc(opts.value || '')+'\" '+\n        'placeholder=\"'+esc(opts.placeholder || '')+'\">'+\n      '<div class=\"dlg-a\">'+\n        '<button type=\"button\" data-v=\"0\">Отмена</button>'+\n        '<button type=\"button\" data-v=\"1\" class=\"btn-primary\">'+esc(opts.ok || 'Готово')+'</button>'+\n      '</div></div>';\n    document.body.appendChild(el);\n\n    var inp = el.querySelector('#dlgIn');\n    var done = function(v){\n      if(!el.parentNode) return;\n      document.removeEventListener('keydown', onKey, true);\n      el.remove();\n      resolve(v);\n    };\n    var onKey = function(e){\n      if(e.key === 'Escape'){ e.preventDefault(); done(null); }\n      else if(e.key === 'Enter'){ e.preventDefault(); done(inp.value.trim()); }\n    };\n    document.addEventListener('keydown', onKey, true);\n    el.addEventListener('click', function(e){\n      if(e.target === el){ done(null); return; }\n      var b = e.target.closest('button[data-v]');\n      if(b) done(b.dataset.v === '1' ? inp.value.trim() : null);\n    });\n    setTimeout(function(){ try{ inp.focus(); inp.select(); }catch(e){} }, 60);\n  });\n}\n\n/** Короткая обёртка: «есть несохранённые правки — продолжить?». */\nfunction askDirty(action){\n  return ask({\n    title: 'Есть несохранённые правки',\n    html: 'Изменения по этому подразделению ещё не отправлены в таблицу. ' +\n          'Если продолжить, они пропадут.',\n    ok: action,\n    cancel: 'Остаться',\n    danger: true\n  });\n}\n\nfunction show(scr){\n  $('scrLogin').classList.toggle('hidden', scr!=='login');\n  $('scrLoad').classList.toggle('hidden', scr!=='load');\n  $('app').classList.toggle('hidden', scr!=='app');\n}\n\n/**\n * Набор кнопок-переключателей.\n * multi=true — можно выбрать несколько; req=true — снять выбор нельзя (обязательное поле).\n */\nfunction chips(act, list, value, multi, req){\n  var sel = multi ? (value||[]) : [value];\n  return '<div class=\"chips\" data-chips=\"'+act+'\"'+(multi?' data-multi=\"1\"':'')+\n         (req?' data-req=\"1\"':'')+'>' +\n    list.map(function(v){\n      var on = sel.indexOf(v) >= 0;\n      return '<button type=\"button\" data-act=\"'+act+'\" data-v=\"'+esc(v)+'\"'+(on?' class=\"on\"':'')+'>'+esc(v)+'</button>';\n    }).join('') + '</div>';\n}\n\n/** Поле, которое открывает экран выбора из справочника. */\nfunction pickField(id, value, placeholder, need){\n  return '<button type=\"button\" class=\"pick'+(need&&!value?' need':'')+'\" id=\"'+id+'\">'+\n    '<span class=\"'+(value?'':'ph')+'\">'+esc(value || placeholder)+'</span><i>выбрать ▾</i></button>';\n}\n\n/**\n * Экран выбора значения из справочника: поиск + строгий список.\n * Свободного ввода нет — иначе одна и та же должность попадает в таблицу\n * в пяти написаниях. Если нужного значения нет, его добавляют кнопкой внизу,\n * и оно сразу появляется у всех остальных.\n *\n * opts = { title, block, list, value, placeholder, onPick,\n *          wide: [полный список], wideLabel, addUnit }\n * wide — второй список «по всему холдингу». Нужен должностям: у руководителя\n * показывается штатка его подразделения, но иногда должность лежит шире.\n */\nfunction openPicker(opts){\n  var el = document.createElement('div');\n  el.className = 'sheet';\n  el.innerHTML = '<div class=\"sheet-in\">'+\n    '<div class=\"sheet-hd\"><b>'+esc(opts.title)+'</b>'+\n      '<button class=\"btn-ghost\" data-x=\"1\">Закрыть</button></div>'+\n    '<div class=\"pk-search\">'+\n      '<input id=\"pkQ\" placeholder=\"Поиск…\" autocomplete=\"off\" autocapitalize=\"off\" '+\n        'autocorrect=\"off\" spellcheck=\"false\"></div>'+\n    '<div id=\"pkBody\"></div>'+\n    '<div style=\"height:10px\"></div></div>';\n  document.body.appendChild(el);\n\n  var q = el.querySelector('#pkQ');\n  var body = el.querySelector('#pkBody');\n  var wideOn = false;                      // показан ли полный список холдинга\n\n  function current(){ return (wideOn ? opts.wide : opts.list) || []; }\n\n  function draw(){\n    var s = q.value.trim().toLowerCase();\n    var src = current();\n    var list = src.filter(function(v){\n      return !s || String(v).toLowerCase().indexOf(s) >= 0;\n    });\n    var exact = src.some(function(v){ return String(v).toLowerCase() === s; });\n\n    var h = '';\n    if(list.length){\n      h += '<div class=\"pk-list\">'+ list.slice(0,300).map(function(v){\n        return '<button type=\"button\" data-v=\"'+esc(v)+'\"'+\n          (v===opts.value?' class=\"on\"':'')+'>'+esc(v)+'</button>';\n      }).join('') +'</div>';\n      if(list.length > 300) h += '<div class=\"pk-empty\">Показаны первые 300 — уточните поиск</div>';\n    } else {\n      h += '<div class=\"pk-empty\">'+\n        (s ? 'Совпадений нет'\n           : (wideOn ? 'Справочник пока пуст'\n                     : 'Для вашего подразделения должности ещё не заведены')) +'</div>';\n    }\n\n    // Переключатель на полный список холдинга\n    if(opts.wide && opts.wide.length){\n      h += '<div class=\"pk-add\"><button type=\"button\" class=\"btn-line\" id=\"pkWide\">'+\n        (wideOn ? '← Только должности моего подразделения'\n                : (opts.wideLabel || 'Показать все должности холдинга')+\n                  ' ('+opts.wide.length+')')+'</button></div>';\n    }\n\n    // Нет точного совпадения — предлагаем добавить своё значение\n    if((opts.block || opts.addUnit) && s.length >= 2 && !exact){\n      h += '<div class=\"pk-add\"><button type=\"button\" class=\"btn-line\" id=\"pkAdd\" '+\n        'style=\"color:var(--accent);border-color:var(--accent)\">'+\n        '+ Добавить: <b>'+esc(q.value.trim())+'</b></button>'+\n        '<p style=\"font-size:12.5px;color:var(--muted);margin:8px 2px 0\">'+\n        (opts.addUnit\n          ? 'Должность добавится в штатку подразделения «'+esc(opts.addUnit)+'».'\n          : 'Значение попадёт в «Справочник» и станет доступно всем.')+'</p></div>';\n    }\n    body.innerHTML = h;\n  }\n  draw();\n  q.oninput = draw;\n\n  function done(v){ el.remove(); opts.onPick(v); }\n\n  el.addEventListener('click', function(e){\n    if(e.target === el || e.target.dataset.x){ el.remove(); return; }\n\n    if(e.target.closest('#pkWide')){\n      wideOn = !wideOn;\n      draw();\n      return;\n    }\n\n    var add = e.target.closest('#pkAdd');\n    if(add){\n      var name = q.value.trim();\n      add.disabled = true; add.textContent = 'Добавляем…';\n\n      var req = opts.addUnit\n        ? call('apiAddPosition', S.token, opts.addUnit, name)\n        : call('apiAddRefValue', S.token, opts.block, name);\n\n      req.then(function(r){\n        if(!r || !r.ok){\n          add.disabled = false;\n          toast((r && r.error) || 'Не удалось добавить');\n          draw();\n          return;\n        }\n        // Обновляем списки у себя, чтобы не перезагружать всю форму\n        if(opts.addUnit){\n          S.data.positions = r.list;\n          S.data.positionsAll = r.all;\n          // штатка текущего подразделения тоже пополняется — иначе новая должность\n          // не появится в чек-листе шага 2 до перезагрузки формы\n          if(S.data.positionsByUnit && S.unit){\n            var pu = S.data.positionsByUnit[S.unit] || (S.data.positionsByUnit[S.unit] = []);\n            if(pu.indexOf(r.name) === -1) pu.push(r.name);\n          }\n          opts.list = r.list;\n          opts.wide = r.all;\n        } else {\n          if(opts.block === 'segments') S.data.segments = r.list;\n          if(opts.block === 'regions') S.data.regions = r.list;\n          opts.list = r.list;\n        }\n        toast('Добавлено в справочник');\n        done(r.name);\n      }).catch(function(){\n        add.disabled = false;\n        toast('Нет связи с сервером');\n        draw();\n      });\n      return;\n    }\n\n    var b = e.target.closest('.pk-list button[data-v]');\n    if(b) done(b.dataset.v);\n  });\n\n  // На телефоне клавиатура закрывает половину экрана — фокус даём не сразу,\n  // чтобы человек сначала увидел список целиком\n  if((opts.list || []).length > 12){\n    setTimeout(function(){ try{ q.focus(); }catch(e){} }, 120);\n  }\n}\n\n// ═══════════════════════════════════════════════════════════\n// СТАРТ\n// ═══════════════════════════════════════════════════════════\n/**\n * Экран входа. Ссылку на форму и доступ человек получает в боте,\n * поэтому здесь только логин и пароль — без кнопки «получить доступ».\n */\n(function loginScreen(){\n  $('loginHelp').innerHTML =\n    '<p style=\"text-align:center;color:var(--muted);font-size:13px;margin-top:16px\">'+\n    'Логин и пароль присылает бот. Не приходил — обратитесь к своему HR BP.</p>';\n})();\n\n(function start(){\n  var t = store.get(LS_TOKEN);\n  if(!t){\n    show('login');\n    try{ $('inLogin').focus(); }catch(e){}\n    return;\n  }\n  show('load');\n  call('apiResume', t).then(function(r){\n    if(r && r.ok){ S.token = r.token; onLoaded(r.data); }\n    else { store.del(LS_TOKEN); show('login'); }\n  }).catch(function(){ store.del(LS_TOKEN); show('login'); });\n})();\n\n$('btnLogin').onclick = doLogin;\n$('inPass').addEventListener('keydown', function(e){ if(e.key==='Enter') doLogin(); });\n$('inLogin').addEventListener('keydown', function(e){ if(e.key==='Enter') $('inPass').focus(); });\n\nfunction doLogin(){\n  var l = $('inLogin').value.trim(), p = $('inPass').value;\n  if(!l || !p){ loginErr('Введите логин и пароль'); return; }\n  $('btnLogin').disabled = true; $('btnLogin').textContent = 'Проверяем…';\n  call('apiLogin', l, p).then(function(r){\n    $('btnLogin').disabled = false; $('btnLogin').textContent = 'Войти';\n    if(!r || !r.ok){ loginErr((r&&r.error)||'Ошибка входа'); return; }\n    S.token = r.token;\n    store.set(LS_TOKEN, r.token);\n    $('inPass').value = '';\n    onLoaded(r.data);\n  }).catch(function(){\n    $('btnLogin').disabled = false; $('btnLogin').textContent = 'Войти';\n    loginErr('Нет связи с сервером. Проверьте интернет.');\n  });\n}\nfunction loginErr(m){ var e=$('loginErr'); e.textContent=m; e.classList.remove('hidden'); }\n\nfunction doLogout(){\n  var go = function(){ store.del(LS_TOKEN); location.reload(); };\n  if(!S.dirty){ go(); return; }\n  askDirty('Выйти без сохранения').then(function(yes){ if(yes) go(); });\n}\n\nfunction doRefresh(){\n  if(!S.dirty){ doRefresh_(); return; }\n  askDirty('Перечитать из таблицы').then(function(yes){ if(yes) doRefresh_(); });\n}\n\nfunction doRefresh_(){\n  toast('Обновляем…');\n  call('apiRefresh', S.token).then(function(r){\n    if(!r || !r.ok){ toast((r&&r.error)||'Не удалось обновить'); return; }\n    S.dirty = false;\n    onLoaded(r.data);\n    toast('Данные перечитаны из таблицы');\n  }).catch(function(){ toast('Нет связи'); });\n}\n\n/** Меню в шапке */\n$('btnMenu').onclick = function(){\n  var r = S.data && S.data.user && S.data.user.role;\n  var items = [];\n  if(r === 'admin' || r === 'cb' || r === 'hrbp' || r === 'dir_head') {\n    items.push(['dash_analytics', '📊 Аналитический дашборд']);\n  }\n  if(r === 'admin' || r === 'cb') {\n    items.push(['admin_panel', '⚙️ Панель администратора']);\n  }\n  if(r === 'hrbp') {\n    items.push(['dash_hrbp', '📋 Сводка по HR BP']);\n  }\n  items.push(['units_view', '🏢 Мои подразделения']);\n  items.push(['refresh', '🔄 Обновить данные из таблицы']);\n  items.push(['help', '❓ Как заполнять']);\n  items.push(['pwd', '🔑 Сменить пароль']);\n  items.push(['out', '🚪 Выйти']);\n\n  var el = document.createElement('div');\n  el.className = 'sheet';\n  el.innerHTML = '<div class=\"sheet-in\">'+\n    '<div class=\"sheet-hd\"><b>'+esc(userLabel())+'</b>'+\n      '<button class=\"btn-ghost\" data-x=\"1\">Закрыть</button></div>'+\n    '<div class=\"menu\">'+ items.map(function(it){\n      return '<button data-go=\"'+it[0]+'\"'+(it[0]==='out'?' class=\"btn-danger\"':'')+'>'+esc(it[1])+'</button>';\n    }).join('') +'</div></div>';\n  document.body.appendChild(el);\n\n  el.addEventListener('click', function(e){\n    if(e.target === el || e.target.dataset.x){ el.remove(); return; }\n    var b = e.target.closest('button[data-go]');\n    if(!b) return;\n    el.remove();\n    var g = b.dataset.go;\n    if(g === 'dash_analytics') switchView('dashboard');\n    else if(g === 'admin_panel') switchView('admin');\n    else if(g === 'dash_hrbp') openDash();\n    else if(g === 'units_view') switchView('units');\n    else if(g === 'refresh') doRefresh();\n    else if(g === 'help') openHelp();\n    else if(g === 'pwd') openPassword();\n    else if(g === 'out') doLogout();\n  });\n};\n\nfunction renderTopNav(){\n  var r = S.data && S.data.user && S.data.user.role;\n  var isSpecial = (r === 'admin' || r === 'cb' || r === 'hrbp' || r === 'dir_head');\n  var topNav = $('topNav');\n  if(!isSpecial || S.unit !== null){\n    topNav.classList.add('hidden');\n    return;\n  }\n  topNav.classList.remove('hidden');\n  var btns = [];\n  btns.push({ id:'units', label:'🏢 Подразделения' });\n  btns.push({ id:'dashboard', label:'📊 Дашборд' });\n  if(r === 'admin' || r === 'cb'){\n    btns.push({ id:'admin', label:'⚙️ Админка' });\n  }\n\n  topNav.innerHTML = btns.map(function(b){\n    var on = S.appView === b.id ? ' on' : '';\n    return '<button class=\"nav-btn'+on+'\" data-view=\"'+b.id+'\">'+esc(b.label)+'</button>';\n  }).join('');\n\n  topNav.onclick = function(e){\n    var b = e.target.closest('button[data-view]');\n    if(!b) return;\n    var v = b.dataset.view;\n    if(v === S.appView && S.unit === null) return;\n    if(S.dirty){\n      askDirty('Переключить раздел').then(function(yes){\n        if(yes){ S.dirty = false; switchView(v); }\n      });\n    } else {\n      switchView(v);\n    }\n  };\n}\n\nfunction switchView(v){\n  S.appView = v;\n  S.unit = null;\n  renderTopNav();\n  if(v === 'units') renderUnits();\n  else if(v === 'dashboard') openDashboard();\n  else if(v === 'admin') openAdminPanel();\n}\n\n/** Смена собственного пароля. */\nfunction openPassword(){\n  var el = document.createElement('div');\n  el.className = 'sheet';\n  el.innerHTML = '<div class=\"sheet-in\">'+\n    '<div class=\"sheet-hd\"><b>Сменить пароль</b>'+\n      '<button class=\"btn-ghost\" data-x=\"1\">Закрыть</button></div>'+\n    '<div id=\"pwErr\" class=\"err hidden\"></div>'+\n    '<label class=\"lbl\" style=\"margin-top:6px\">Текущий пароль</label>'+\n    '<input id=\"pwOld\" type=\"password\" autocomplete=\"current-password\">'+\n    '<label class=\"lbl\">Новый пароль</label>'+\n    '<input id=\"pwNew\" type=\"password\" autocomplete=\"new-password\" placeholder=\"минимум 6 символов\">'+\n    '<label class=\"lbl\">Повторите новый</label>'+\n    '<input id=\"pwNew2\" type=\"password\" autocomplete=\"new-password\">'+\n    '<div style=\"height:16px\"></div>'+\n    '<button id=\"pwGo\" class=\"btn-primary\">Сменить пароль</button>'+\n    '<p style=\"font-size:13px;color:var(--muted);margin:14px 0 0;text-align:center\">'+\n      'Запишите новый пароль — восстановить его нельзя,<br>только выдать новый через HR BP.</p>'+\n    '</div>';\n  document.body.appendChild(el);\n\n  var err = function(m){\n    var e = el.querySelector('#pwErr');\n    e.textContent = m; e.classList.remove('hidden');\n  };\n\n  el.addEventListener('click', function(e){\n    if(e.target === el || e.target.dataset.x) el.remove();\n  });\n\n  el.querySelector('#pwGo').onclick = function(){\n    var o = el.querySelector('#pwOld').value;\n    var n = el.querySelector('#pwNew').value;\n    var n2 = el.querySelector('#pwNew2').value;\n    if(!o || !n){ err('Заполните все поля'); return; }\n    if(n.length < 6){ err('Новый пароль — минимум 6 символов'); return; }\n    if(n !== n2){ err('Новые пароли не совпадают'); return; }\n\n    var btn = this;\n    btn.disabled = true; btn.textContent = 'Меняем…';\n    call('apiChangePassword', S.token, o, n).then(function(r){\n      btn.disabled = false; btn.textContent = 'Сменить пароль';\n      if(!r || !r.ok){ err((r && r.error) || 'Не удалось сменить пароль'); return; }\n      el.remove();\n      toast('Пароль изменён. В следующий раз входите с новым.');\n    }).catch(function(){\n      btn.disabled = false; btn.textContent = 'Сменить пароль';\n      err('Нет связи с сервером');\n    });\n  };\n\n  setTimeout(function(){ el.querySelector('#pwOld').focus(); }, 60);\n}\n\n/** Подпись пользователя. Если ФИО в таблице не заполнено — показываем логин. */\nfunction userLabel(){\n  if(!S.data) return '';\n  var f = String(S.data.user.fio || '').trim();\n  if(f.length > 1 && !/^\\d+$/.test(f)) return f;\n  return S.data.user.login;\n}\n\n$('btnHelp').onclick = function(){ openHelp(); };\n\nfunction openHelp(){\n  var el = document.createElement('div');\n  el.className = 'sheet';\n  el.innerHTML = '<div class=\"sheet-in\">'+\n    '<div class=\"sheet-hd\"><b>Как заполнять</b>'+\n      '<button class=\"btn-ghost\" data-x=\"1\">Закрыть</button></div>'+\n    '<ol class=\"howto\">'+\n      '<li><b>Откройте своё подразделение</b><br>Если их несколько — по очереди каждое.</li>'+\n      '<li><b>Шаг 1. Конкуренты</b><br>По каждой компании нажмите одну из трёх кнопок: '+\n        '«Актуально» — это наш конкурент, «Не актуально» — нет, «Уточнить» — не уверены. '+\n        'Чего не хватает — добавьте кнопкой «+ Добавить компанию».</li>'+\n      '<li><b>«Уточнить» — это не «проверено»</b><br>Такие компании остаются в работе '+\n        'и отдельно видны и вам, и HR BP. Вернитесь к ним, когда выясните.</li>'+\n      '<li><b>Шаг 2. Данные по рынку</b><br>Здесь главное. По должностям, которые знаете, '+\n        'внесите оклад, бонусы и льготы у конкурента. Неполные данные тоже нужны — '+\n        'знаете только оклад, впишите оклад.</li>'+\n      '<li><b>Должность выбирается из списка</b><br>Нажмите на поле, найдите нужную через поиск. '+\n        'Если такой нет — внизу появится кнопка «Добавить», и должность попадёт в общий справочник.</li>'+\n      '<li><b>Нажмите «Сохранить»</b><br>Одна кнопка сохраняет оба шага сразу. '+\n        'Данные попадают в таблицу немедленно.</li>'+\n    '</ol>'+\n    '<div class=\"callout-h\">Можно заполнять в несколько заходов — просто сохраняйте по ходу. '+\n      'Когда всё готово, нажмите «Сохранить и отправить как готовое» на шаге 1.</div>'+\n    '<div style=\"height:14px\"></div>'+\n    '<button class=\"btn-primary\" data-x=\"1\">Понятно</button></div>';\n  document.body.appendChild(el);\n  el.addEventListener('click', function(e){\n    if(e.target === el || e.target.dataset.x) el.remove();\n  });\n}\n\nfunction onLoaded(data){\n  S.data = data;\n  var isElevated = (data.user.role === 'admin' || data.user.role === 'cb');\n  S.ro = !!(data.period && data.period.state === 'закрыт' && data.user.role !== 'hrbp' && !isElevated);\n  show('app');\n  renderTopNav();\n  if(data.needsUnitPick) renderUnitPicker();\n  else if(S.appView === 'dashboard') openDashboard();\n  else if(S.appView === 'admin') openAdminPanel();\n  else renderUnits();\n}\n\n/** Плашка о состоянии периода. */\nfunction periodBanner(){\n  var p = S.data.period || {};\n  if(p.state === 'закрыт'){\n    return '<div class=\"note\"><b>Период заполнения закрыт</b>' +\n      (p.name ? ' — ' + esc(p.name) : '') + (p.to ? ', ' + esc(p.to) : '') + '.<br>' +\n      (S.data.user.role === 'hrbp'\n        ? 'Вы HR BP — правка доступна. Открыть период можно в разделе «Сводка».'\n        : 'Данные доступны только для просмотра.') + '</div>';\n  }\n  return p.name ? '<div class=\"info\">Идёт: <b>' + esc(p.name) + '</b>' +\n    (p.to ? ' · до ' + esc(p.to) : '') + '</div>' : '';\n}\n\n// ═══════════════════════════════════════════════════════════\n// ЭКРАН: выбор подразделения\n// ═══════════════════════════════════════════════════════════\nfunction renderUnitPicker(){\n  setTop('Выберите подразделение', userLabel(), false);\n  $('body').onclick = null;\n  $('body').innerHTML =\n    '<div class=\"note\">За вами пока не закреплено подразделение. ' +\n    'Отметьте те, по которым вы отвечаете за обзор рынка.</div>' +\n    '<input id=\"pickFind\" placeholder=\"Поиск по названию…\"><div id=\"pickList\"></div>' +\n    '<div style=\"height:14px\"></div><button id=\"pickGo\" class=\"btn-primary\">Продолжить</button>';\n  var chosen = {};\n  function draw(){\n    var q = ($('pickFind').value||'').toLowerCase();\n    $('pickList').innerHTML = S.data.allUnits.filter(function(u){\n      return !q || u.unit.toLowerCase().indexOf(q) >= 0 || u.dir.toLowerCase().indexOf(q) >= 0;\n    }).slice(0,80).map(function(u){\n      return '<label class=\"pickrow\"><input type=\"checkbox\" data-u=\"'+esc(u.unit)+'\"'+\n        (chosen[u.unit]?' checked':'')+'><span>'+esc(u.unit)+\n        '<br><small style=\"color:var(--muted)\">'+esc(u.dir)+'</small></span></label>';\n    }).join('') || '<p style=\"color:var(--muted)\">Ничего не найдено</p>';\n  }\n  draw();\n  $('pickFind').oninput = draw;\n  $('pickList').onchange = function(e){\n    if(e.target.dataset.u) chosen[e.target.dataset.u] = e.target.checked;\n  };\n  $('pickGo').onclick = function(){\n    var list = Object.keys(chosen).filter(function(k){ return chosen[k]; });\n    if(!list.length){ toast('Отметьте хотя бы одно подразделение'); return; }\n    this.disabled = true; this.textContent = 'Сохраняем…';\n    call('apiSetUnits', S.token, list).then(function(r){\n      if(r && r.ok){ S.data = r.data; renderUnits(); }\n      else { toast((r&&r.error)||'Ошибка'); $('pickGo').disabled=false; $('pickGo').textContent='Продолжить'; }\n    });\n  };\n}\n\n// ═══════════════════════════════════════════════════════════\n// ЭКРАН: список подразделений\n// ═══════════════════════════════════════════════════════════\nfunction renderUnits(){\n  S.unit = null; S.dirty = false;\n  setTop('Мои подразделения', userLabel(), false);\n  $('bar').classList.add('hidden');\n\n  var u = S.data.units;\n  if(!u.length){\n    $('body').innerHTML = periodBanner() + '<div class=\"note\">Подразделения не назначены. Обратитесь к HR BP.</div>';\n    return;\n  }\n  var totalAll = 0, doneAll = 0, askAll = 0, svAll = 0;\n  u.forEach(function(x){\n    totalAll += x.total; doneAll += x.done; askAll += (x.ask||0); svAll += (x.surveys||0);\n  });\n\n  var h = periodBanner();\n\n  // Пока человек ничего не заполнил — объясняем, что вообще нужно сделать\n  if(store.get(LS_OB) !== '1'){\n    h += '<div class=\"onboard\"><h2>Что нужно сделать</h2><ol>'+\n      '<li>Открыть <b>своё подразделение</b> в списке ниже.</li>'+\n      '<li><b>Шаг 1</b> — отметить, какие компании вам конкуренты.</li>'+\n      '<li><b>Шаг 2</b> — внести зарплаты, бонусы и льготы у этих компаний.</li>'+\n      '<li>Нажать <b>«Сохранить»</b>.</li>'+\n      '</ol><div class=\"ob-act\">'+\n      '<button id=\"obMore\">Подробнее</button>'+\n      '<button id=\"obHide\" class=\"btn-primary\" style=\"width:auto\">Понятно, скрыть</button>'+\n      '</div></div>';\n  }\n\n  h += '<div class=\"sec-title\">Компаний к проверке: '+totalAll+' · проверено '+doneAll+\n       (askAll ? ' · требует уточнения '+askAll : '') +\n       ' · записей по должностям: '+svAll+'</div>';\n  h += u.map(function(x,i){\n    var pct = x.total ? Math.round(x.done/x.total*100) : 0;\n    var askPct = x.total ? Math.round((x.ask||0)/x.total*100) : 0;\n    return '<div class=\"unit\" data-i=\"'+i+'\">'+ring(pct, askPct)+\n      '<div class=\"u-body\"><div class=\"u-name\">'+esc(x.unit)+'</div>'+\n      '<div class=\"u-dir\">'+esc(x.dir)+' · '+x.done+' из '+x.total+\n      ' · данных: '+(x.surveys||0)+'</div>'+\n      ((x.ask||0) ? '<div class=\"u-ask\">требует уточнения: '+x.ask+'</div>' : '')+\n      '</div>'+\n      '<div class=\"u-chev\">›</div></div>';\n  }).join('');\n  $('body').innerHTML = h;\n  if($('obMore')) $('obMore').onclick = openHelp;\n  if($('obHide')) $('obHide').onclick = function(){ store.set(LS_OB, '1'); renderUnits(); };\n  $('body').onclick = function(e){\n    var el = e.target.closest('.unit');\n    if(el) openUnit(S.data.units[+el.dataset.i].unit);\n  };\n}\n\n/**\n * Кольцо прогресса: зелёная дуга — проверено, жёлтая — «уточнить».\n * «Уточнить» намеренно не входит в процент: вопрос ещё не закрыт.\n */\nfunction ring(pct, askPct){\n  var r = 19, c = 2*Math.PI*r;\n  var donePart = c * (pct/100);\n  var askPart = c * ((askPct||0)/100);\n  var col = pct>=100 ? 'var(--ok)' : (pct>0 ? 'var(--warn)' : 'var(--line)');\n  var h = '<div class=\"ring\"><svg width=\"46\" height=\"46\">'+\n    '<circle cx=\"23\" cy=\"23\" r=\"'+r+'\" fill=\"none\" stroke=\"var(--line)\" stroke-width=\"4\"/>';\n  if(askPart > 0){\n    // жёлтую дугу рисуем сразу за зелёной\n    h += '<circle cx=\"23\" cy=\"23\" r=\"'+r+'\" fill=\"none\" stroke=\"var(--warn)\" stroke-width=\"4\"'+\n      ' stroke-dasharray=\"'+askPart.toFixed(1)+' '+(c-askPart).toFixed(1)+'\"'+\n      ' stroke-dashoffset=\"'+(-donePart).toFixed(1)+'\"/>';\n  }\n  if(donePart > 0){\n    h += '<circle cx=\"23\" cy=\"23\" r=\"'+r+'\" fill=\"none\" stroke=\"'+col+'\" stroke-width=\"4\"'+\n      ' stroke-dasharray=\"'+donePart.toFixed(1)+' '+(c-donePart).toFixed(1)+'\"'+\n      ' stroke-dashoffset=\"0\" stroke-linecap=\"round\"/>';\n  }\n  return h + '</svg><b>'+pct+'%</b></div>';\n}\n\nfunction setTop(title, sub, back){\n  $('ttl').innerHTML = esc(title) + (sub ? '<span class=\"sub\"> · '+esc(sub)+'</span>' : '');\n  $('btnBack').classList.toggle('hidden', !back);\n  window.scrollTo(0,0);\n}\n$('btnBack').onclick = function(){\n  var go = function(){ S.dirty = false; renderUnits(); };\n  if(!S.dirty){ go(); return; }\n  askDirty('Выйти без сохранения').then(function(yes){ if(yes) go(); });\n};\n\n// ═══════════════════════════════════════════════════════════\n// ЭКРАН: подразделение (две вкладки)\n// ═══════════════════════════════════════════════════════════\nfunction openUnit(unit){\n  S.unit = unit;\n  S.tab = 'comp';\n  S.rows = S.data.rows.filter(function(r){ return r.unit === unit; })\n                      .map(function(r){ return JSON.parse(JSON.stringify(r)); });\n  S.surveys = S.data.surveys.filter(function(r){ return r.unit === unit; })\n                            .map(function(r){ return JSON.parse(JSON.stringify(r)); });\n  S.added = []; S.removed = []; S.note = ''; S.dirty = false;\n\n  var d = null;\n  if(!S.ro){\n    try{ d = JSON.parse(store.get(LS_DRAFT+unit) || 'null'); }catch(e){ d = null; }\n  }\n  if(!d){ renderUnit(); return; }\n\n  ask({\n    title: 'Найден черновик',\n    html: 'По подразделению <b>'+esc(unit)+'</b> остались правки, которые не были ' +\n          'отправлены в таблицу — например, вкладку закрыли до сохранения.',\n    ok: 'Восстановить',\n    cancel: 'Начать заново'\n  }).then(function(yes){\n    if(yes){\n      S.rows = d.rows || S.rows; S.added = d.added || [];\n      S.surveys = d.surveys || S.surveys; S.removed = d.removed || [];\n      S.note = d.note || ''; S.dirty = true;\n    } else {\n      store.del(LS_DRAFT+unit);\n    }\n    renderUnit();\n  });\n}\n\n/** Сколько компаний проверено, сколько отложено на уточнение. */\nfunction counts(){\n  var all = S.rows.length + S.added.length;\n  var done = 0, ask = 0;\n  S.rows.forEach(function(r){\n    if(r.actual === 'уточнить') ask++;\n    else if(r.actual && r.actual !== 'не проверено') done++;\n  });\n  S.added.forEach(function(r){\n    if(r.actual === 'уточнить') ask++;\n    else if(r.actual && r.actual !== 'не проверено') done++;\n  });\n  return { all: all, done: done, ask: ask, left: all - done - ask };\n}\n\nfunction renderUnit(){\n  setTop(S.unit, '', true);\n  $('body').onclick = null;\n\n  var c = counts();\n  var step1done = c.all > 0 && c.done === c.all;\n\n  var cls = function(tab, done){\n    return (S.tab===tab ? 'on' : '') + (done ? ' done' : '');\n  };\n\n  var h = periodBanner();\n  h += '<div class=\"tabs\">'+\n    '<button data-tab=\"comp\" class=\"'+cls('comp', step1done)+'\">'+\n      '<small>Шаг 1</small>Конкуренты · '+c.done+'/'+c.all+\n      (c.ask ? ' <span style=\"color:var(--warn)\">?'+c.ask+'</span>' : '')+'</button>'+\n    '<button data-tab=\"survey\" class=\"'+cls('survey', S.surveys.length>0)+'\">'+\n      '<small>Шаг 2</small>Данные по рынку · '+svLabel()+'</button>'+\n    '</div>';\n  h += '<p class=\"step-hint\">'+ (S.tab==='comp'\n      ? 'Отметьте по каждой компании, конкурент она вам или нет. Не уверены — «Уточнить»: такие останутся в работе.'\n      : 'Внесите оклады, бонусы и льготы по должностям, которые знаете. Неполные данные тоже нужны.'\n    ) +'</p>';\n  h += '<div id=\"tabBody\"></div>';\n  $('body').innerHTML = h;\n\n  $('body').querySelector('.tabs').onclick = function(e){\n    var b = e.target.closest('button[data-tab]');\n    if(!b || b.dataset.tab === S.tab) return;\n    S.tab = b.dataset.tab;\n    renderUnit();\n  };\n\n  if(S.tab === 'comp') renderTabComp();\n  else renderTabSurvey();\n\n  $('bar').classList.remove('hidden');\n  updateProgress();\n}\n\n// ─────────── Вкладка 1: конкуренты ───────────\nfunction renderTabComp(){\n  var c = counts();\n  var h = '';\n\n  // Отложенные на уточнение показываем отдельно — иначе они теряются в общем списке\n  if(c.ask){\n    h += '<div class=\"note\">Требует уточнения: <b>'+c.ask+'</b>. '+\n      'Эти компании не считаются проверенными — вернитесь к ним, когда выясните.</div>';\n  }\n\n  h += '<div class=\"sec-title\">Компании в вашей карте</div><div id=\"rows\">';\n  h += S.rows.map(function(r,i){ return rowCard(r, i, false); }).join('') ||\n       '<div class=\"empty\">Список пуст</div>';\n  h += '</div>';\n\n  if(S.added.length){\n    h += '<div class=\"sec-title\">Добавленные, ещё не сохранены</div><div id=\"adds\">';\n    h += S.added.map(function(r,i){ return rowCard(r, i, true); }).join('');\n    h += '</div>';\n  } else { h += '<div id=\"adds\"></div>'; }\n\n  if(!S.ro) h += '<button id=\"btnAdd\" class=\"btn-line\" style=\"margin-top:6px\">+ Добавить компанию</button>';\n\n  h += '<label class=\"lbl\" style=\"margin-top:22px\">Комментарий по подразделению</label>';\n  h += '<textarea id=\"unitNote\" placeholder=\"Что важно знать о рынке труда вашего подразделения\"'+\n       (S.ro?' disabled':'')+'>'+esc(S.note)+'</textarea>';\n\n  if(!S.ro){\n    h += '<div class=\"next-step\">';\n    h += '<p>'+ (c.left\n        ? 'Осталось отметить компаний: '+c.left+\n          (c.ask ? ', плюс '+c.ask+' на уточнении' : '')+\n          '. Можно перейти к шагу 2 и вернуться позже.'\n        : (c.ask\n            ? 'Все компании отмечены, но '+c.ask+' ждут уточнения. Дальше — зарплаты и льготы.'\n            : 'Шаг 1 пройден. Дальше — самое важное: зарплаты и льготы.')) +'</p>';\n    h += '<button id=\"btnNext\" class=\"btn-primary\">Перейти к шагу 2 · Данные по рынку →</button>';\n    h += '<div style=\"height:10px\"></div>';\n    h += '<button id=\"btnSubmit\" class=\"btn-line\" style=\"color:var(--ok);border-color:var(--ok)\">'+\n         'Всё готово — отправить</button>';\n    h += '</div>';\n  }\n\n  $('tabBody').innerHTML = h;\n  bindRows();\n  $('unitNote').oninput = function(){ S.note = this.value; markDirty(); };\n  if($('btnAdd')) $('btnAdd').onclick = openAddSheet;\n  if($('btnNext')) $('btnNext').onclick = function(){ S.tab = 'survey'; renderUnit(); };\n  if($('btnSubmit')) $('btnSubmit').onclick = function(){ save(true); };\n}\n\nfunction rowCard(r, i, isNew){\n  var st = r.actual === 'актуально' ? 'st-yes'\n         : r.actual === 'не актуально' ? 'st-no'\n         : r.actual === 'уточнить' ? 'st-ask' : '';\n  var meta = [r.seg, r.region].filter(String).join(' · ');\n  var name = r.company || '(название не заполнено в таблице)';\n  var h = '<div class=\"row '+st+'\" data-i=\"'+i+'\">';\n  h += '<div class=\"row-head\"><div class=\"row-name\"'+\n       (r.company?'':' style=\"color:var(--muted);font-weight:400;font-style:italic\"')+'>'+\n       esc(name)+(isNew?' <span class=\"pill p-ok\">новая</span>':'')+'</div>';\n  if(meta) h += '<div class=\"row-meta\">'+esc(meta)+'</div>';\n  if(r.actual === 'уточнить') h += '<div class=\"row-ask\">не считается проверенной</div>';\n  if(r.note) h += '<div class=\"row-note-preview\">'+esc(r.note)+'</div>';\n  h += '</div>';\n\n  h += '<div class=\"seg\">'+\n    ['актуально','не актуально','уточнить'].map(function(v){\n      return '<button data-act=\"actual\" data-v=\"'+v+'\"'+(r.actual===v?' class=\"on\"':'')+\n        (S.ro?' disabled':'')+'>'+\n        (v==='актуально'?'Актуально':v==='не актуально'?'Не актуально':'Уточнить')+'</button>';\n    }).join('')+'</div>';\n\n  h += '<button class=\"toggle-more\" data-act=\"more\">Подробнее ▾</button>';\n  h += '<div class=\"more hidden\">';\n  h += '<div style=\"font-size:12.5px;color:var(--muted);margin:8px 0 5px;font-weight:600\">Тип конкурента</div>';\n  h += chips('type', S.data.ref.types, r.type, false);\n  h += '<div style=\"font-size:12.5px;color:var(--muted);margin:12px 0 5px;font-weight:600\">Приоритет</div>';\n  h += chips('prio', S.data.ref.priorities, r.prio, false);\n  h += '<label class=\"lbl\">Комментарий'+\n       (r.actual === 'уточнить' ? ' — что именно уточнить' : '')+'</label>';\n  h += '<textarea data-act=\"note\" placeholder=\"'+\n       (r.actual === 'уточнить' ? 'Что нужно выяснить и у кого' : 'Почему важен / что учесть')+\n       '\"'+(S.ro?' disabled':'')+'>'+esc(r.note||'')+'</textarea>';\n  h += '</div></div>';\n  return h;\n}\n\nfunction bindRows(){\n  ['rows','adds'].forEach(function(zone){\n    var box = $(zone);\n    if(!box) return;\n    box.addEventListener('click', function(e){\n      var b = e.target.closest('button');\n      if(!b) return;\n      var card = b.closest('.row');\n      var arr = zone === 'rows' ? S.rows : S.added;\n      var r = arr[+card.dataset.i];\n      var act = b.dataset.act;\n\n      if(act === 'more'){\n        var m = card.querySelector('.more');\n        var closed = m.classList.toggle('hidden');\n        b.textContent = closed ? 'Подробнее ▾' : 'Свернуть ▴';\n        return;\n      }\n      if(S.ro) return;\n      if(act === 'actual'){\n        r.actual = (r.actual === b.dataset.v) ? 'не проверено' : b.dataset.v;\n        card.className = 'row ' + (r.actual==='актуально'?'st-yes':r.actual==='не актуально'?'st-no':\n                                   r.actual==='уточнить'?'st-ask':'');\n        card.querySelectorAll('.seg button').forEach(function(x){\n          x.classList.toggle('on', x.dataset.v === r.actual); });\n        // подпись «не считается проверенной» появляется и исчезает сразу\n        var head = card.querySelector('.row-head');\n        var mark = head.querySelector('.row-ask');\n        if(r.actual === 'уточнить' && !mark){\n          var d = document.createElement('div');\n          d.className = 'row-ask';\n          d.textContent = 'не считается проверенной';\n          var prev = head.querySelector('.row-note-preview');\n          if(prev) head.insertBefore(d, prev); else head.appendChild(d);\n        } else if(r.actual !== 'уточнить' && mark){ mark.remove(); }\n        markDirty(); updateProgress(); return;\n      }\n      if(act === 'type' || act === 'prio'){\n        r[act] = (r[act] === b.dataset.v) ? '' : b.dataset.v;\n        b.parentNode.querySelectorAll('button').forEach(function(x){\n          x.classList.toggle('on', x.dataset.v === r[act]); });\n        markDirty(); return;\n      }\n    });\n    box.addEventListener('input', function(e){\n      if(e.target.dataset.act !== 'note') return;\n      var card = e.target.closest('.row');\n      var arr = zone === 'rows' ? S.rows : S.added;\n      arr[+card.dataset.i].note = e.target.value;\n      markDirty();\n    });\n  });\n}\n\n// ─────────── Вкладка 2: данные по рынку ───────────\n/**\n * Штатка подразделения и записи, разложенные по должностям.\n * Должности, которых нет в штатке, идут отдельной группой в конце —\n * их вносили вручную, и терять их нельзя.\n */\nfunction survGroups(){\n  var штатка = (S.data.positionsByUnit && S.data.positionsByUnit[S.unit]) || [];\n  var groups = [], byPos = {};\n\n  штатка.forEach(function(p){\n    var g = { pos: p, items: [], extra: false };\n    byPos[norm(p)] = g;\n    groups.push(g);\n  });\n\n  var tail = [];\n  S.surveys.forEach(function(r, i){\n    var g = byPos[norm(r.posOur)];\n    if(g){ g.items.push(i); return; }\n    var t = tail.filter(function(x){ return norm(x.pos) === norm(r.posOur); })[0];\n    if(!t){ t = { pos: r.posOur || '(должность не указана)', items: [], extra: true }; tail.push(t); }\n    t.items.push(i);\n  });\n\n  return { groups: groups.concat(tail), штатка: штатка };\n}\n\nfunction norm(s){ return String(s == null ? '' : s).toLowerCase().replace(/ё/g,'е').replace(/\\s+/g,' ').trim(); }\n\n/** Подпись на вкладке шага 2: «закрыто/всего» по штатке, иначе просто число записей. */\nfunction svLabel(){\n  var g = survGroups();\n  if(!g.groups.length) return String(S.surveys.length);\n  var closed = g.groups.filter(function(x){ return x.items.length; }).length;\n  return closed + '/' + g.groups.length;\n}\n\nfunction renderTabSurvey(){\n  var G = survGroups();\n  var h = '';\n\n  if(!G.штатка.length && !S.surveys.length){\n    h += '<div class=\"empty\"><b>Здесь пока пусто</b><br><br>' +\n         'Для этого подразделения штатка не заведена.<br>' +\n         'Добавьте должность кнопкой ниже — она попадёт и в справочник.<br><br>' +\n         'Одна запись = одна должность в одной компании.</div>';\n  } else {\n    var closed = G.groups.filter(function(g){ return g.items.length; }).length;\n    h += '<div class=\"sec-title\">Должности подразделения · закрыто ' + closed +\n         ' из ' + G.groups.length + '</div>';\n\n    h += G.groups.map(function(g, gi){\n      var n = g.items.length;\n      var cos = g.items.map(function(i){ return S.surveys[i].company; }).filter(String);\n      var cls = 'pos' + (n ? ' pos-done' : '');\n\n      var x = '<div class=\"'+cls+'\">';\n      x += '<div class=\"pos-head\" data-toggle=\"'+gi+'\">';\n      x += '<div class=\"pos-body\"><div class=\"pos-name\">'+esc(g.pos)+\n           (g.extra ? ' <span class=\"pill p-mid\">не в штатке</span>' : '')+'</div>';\n      x += '<div class=\"pos-sub\">'+ (n\n            ? esc(cos.slice(0,3).join(', ')) + (cos.length > 3 ? ' и ещё ' + (cos.length-3) : '')\n            : 'данных нет') +'</div></div>';\n      x += '<div class=\"pos-cnt\">'+(n ? n : '—')+'</div>';\n      if(n) x += '<div class=\"pos-chev\">▾</div>';\n      x += '</div>';\n\n      // записи по должности — скрыты, пока не раскроют\n      x += '<div class=\"pos-items hidden\" data-items=\"'+gi+'\">';\n      x += g.items.map(function(i){ return svCard(S.surveys[i], i); }).join('');\n      if(!S.ro){\n        x += '<button class=\"btn-line\" data-add=\"'+gi+'\" style=\"margin-top:2px\">'+\n             '+ Ещё компания по этой должности</button>';\n      }\n      x += '</div>';\n\n      if(!n && !S.ro){\n        x += '<button class=\"btn-line pos-go\" data-add=\"'+gi+'\">Внести данные</button>';\n      }\n      x += '</div>';\n      return x;\n    }).join('');\n  }\n\n  if(!S.ro){\n    h += '<button id=\"btnAddSv\" class=\"btn-line\" style=\"margin-top:14px\">'+\n         '+ Должность, которой нет в списке</button>';\n  }\n  $('tabBody').innerHTML = h;\n\n  $('tabBody').onclick = function(e){\n    // раскрыть или свернуть должность\n    var head = e.target.closest('.pos-head');\n    if(head && !e.target.closest('button')){\n      var box = $('tabBody').querySelector('[data-items=\"'+head.dataset.toggle+'\"]');\n      if(box && box.children.length){\n        var closedNow = box.classList.toggle('hidden');\n        var chev = head.querySelector('.pos-chev');\n        if(chev) chev.textContent = closedNow ? '▾' : '▴';\n      }\n      return;\n    }\n    // внести данные по конкретной должности — она подставится в форму\n    var add = e.target.closest('button[data-add]');\n    if(add){\n      openSurveySheet(-1, G.groups[+add.dataset.add].pos);\n      return;\n    }\n    var b = e.target.closest('button[data-sv]');\n    if(!b) return;\n    var i = +b.dataset.i;\n    if(b.dataset.sv === 'edit') openSurveySheet(i);\n    if(b.dataset.sv === 'del'){\n      var r = S.surveys[i];\n      ask({\n        title: 'Удалить запись?',\n        html: '<b>'+esc(r.posOur || '(должность не указана)')+'</b>'+\n              (r.company ? ' · '+esc(r.company) : ''),\n        ok: 'Удалить',\n        danger: true\n      }).then(function(yes){\n        if(!yes) return;\n        if(r.id && r.id.indexOf('tmp') !== 0) S.removed.push(r.id);\n        S.surveys.splice(i,1);\n        markDirty();\n        renderUnit();\n        toast('Запись удалена. Нажмите «Сохранить», чтобы применить в таблице.');\n      });\n    }\n  };\n  if($('btnAddSv')) $('btnAddSv').onclick = function(){ openSurveySheet(-1); };\n}\n\nfunction money(r){\n  // значения приходят и как «5 500», и как «5500.5» — сначала приводим к числу\n  var num = function(x){\n    var s = String(x == null ? '' : x).replace(/[\\s ]/g,'').replace(',','.');\n    if(!s) return '';\n    var n = Number(s);\n    if(isNaN(n)) return String(x).trim();\n    return n.toLocaleString('ru-RU');\n  };\n  var f = num(r.payFrom), t = num(r.payTo);\n  if(!f && !t) return '';\n  var s = (f && t) ? (f + ' – ' + t) : (f || t);\n  return s + (r.cur ? ' ' + r.cur : '') + (r.payPer ? ' ' + r.payPer : '');\n}\n\nfunction svCard(r, i){\n  var h = '<div class=\"sv\">';\n  h += '<div class=\"sv-pos\">'+esc(r.posOur || '(должность не указана)')+\n       (r.posTheir ? ' <span style=\"color:var(--muted);font-weight:400\">→ '+esc(r.posTheir)+'</span>' : '')+'</div>';\n  h += '<div class=\"sv-co\">'+esc(r.company || '(компания не указана)')+\n       (r.grade ? ' · '+esc(r.grade) : '')+'</div>';\n  var m = money(r);\n  if(m) h += '<div class=\"sv-pay\">'+esc(m)+'</div>';\n  if(r.bonHas === 'да'){\n    h += '<div class=\"sv-line\">Бонус: '+esc([r.bonSize, r.bonType, r.bonPer].filter(String).join(' · ') || 'есть')+'</div>';\n  } else if(r.bonHas === 'нет'){\n    h += '<div class=\"sv-line\">Бонусов нет</div>';\n  }\n  if(r.extra) h += '<div class=\"sv-line\">Прочее: '+esc(r.extra)+'</div>';\n  if(r.benefits && r.benefits.length){\n    var vis = r.benefits.slice(0,3), rest = r.benefits.length - vis.length;\n    h += '<div class=\"sv-tags\">'+vis.map(function(b){ return '<span>'+esc(b)+'</span>'; }).join('')+\n         (rest>0 ? '<span>+'+rest+'</span>' : '')+'</div>';\n  }\n  if(r.note) h += '<div class=\"sv-line\" style=\"font-style:italic\">'+esc(r.note)+'</div>';\n  var meta = [r.source, r.trust ? 'достоверность: '+r.trust : ''].filter(String).join(' · ');\n  if(meta) h += '<div class=\"sv-by\">'+esc(meta)+'</div>';\n  if(r.by) h += '<div class=\"sv-by\">'+esc(r.by)+(r.at ? ' · '+esc(r.at) : '')+'</div>';\n  if(!S.ro){\n    h += '<div class=\"sv-act\">'+\n      '<button data-sv=\"edit\" data-i=\"'+i+'\">Изменить</button>'+\n      '<button data-sv=\"del\" data-i=\"'+i+'\" class=\"btn-danger\">Удалить</button></div>';\n  }\n  h += '</div>';\n  return h;\n}\n\n/** Форма добавления/правки записи. i = -1 — новая. */\nfunction openSurveySheet(i, presetPos){\n  var isNew = i < 0;\n  var r = isNew\n    ? { id:'', unit:S.unit, company:'', posOur: presetPos || '', posTheir:'', grade:'',\n        payFrom:'', payTo:'', cur:'сомони', payPer:'в месяц',\n        bonHas:'', bonSize:'', bonType:'', bonPer:'',\n        benefits:[], extra:'', source:'', trust:'', note:'' }\n    : JSON.parse(JSON.stringify(S.surveys[i]));\n\n  var ref = S.data.ref;\n  var coList = S.rows.map(function(x){ return x.company; })\n    .concat(S.added.map(function(x){ return x.company; }))\n    .filter(function(v,k,a){ return v && a.indexOf(v) === k; });\n  if(r.company && coList.indexOf(r.company) < 0) coList.unshift(r.company);\n\n  var el = document.createElement('div');\n  el.className = 'sheet';\n  el.innerHTML = '<div class=\"sheet-in\">'+\n    '<div class=\"sheet-hd\"><b>'+(isNew?'Новая запись':'Изменить запись')+'</b>'+\n      '<button class=\"btn-ghost\" data-x=\"1\">Закрыть</button></div>'+\n\n    '<label class=\"lbl\" style=\"margin-top:6px\">Компания-конкурент</label>'+\n    '<select id=\"fCo\">'+\n      '<option value=\"\">— выберите —</option>'+\n      coList.map(function(c){ return '<option'+(c===r.company?' selected':'')+'>'+esc(c)+'</option>'; }).join('')+\n      '<option value=\"__other__\">Другая компания…</option>'+\n    '</select>'+\n    '<input id=\"fCoOther\" class=\"hidden\" placeholder=\"Название компании\" style=\"margin-top:8px\">'+\n\n    '<label class=\"lbl\">Должность у нас</label>'+\n    pickField('fPosOur', r.posOur, 'Выберите должность', true)+\n\n    '<label class=\"lbl\">Как эта должность называется у них</label>'+\n    pickField('fPosTheir', r.posTheir, 'Выберите или добавьте', false)+\n\n    '<label class=\"lbl\">Уровень / грейд (необязательно)</label>'+\n    '<input id=\"fGrade\" value=\"'+esc(r.grade)+'\">'+\n\n    '<label class=\"lbl\">Оклад</label>'+\n    '<div class=\"two\"><div><input id=\"fFrom\" inputmode=\"decimal\" placeholder=\"от\" value=\"'+esc(r.payFrom)+'\"></div>'+\n      '<div><input id=\"fTo\" inputmode=\"decimal\" placeholder=\"до\" value=\"'+esc(r.payTo)+'\"></div></div>'+\n    '<div style=\"height:8px\"></div>'+ chips('cur', ref.currencies, r.cur, false, true) +\n    '<div style=\"height:6px\"></div>'+ chips('payPer', ref.payPeriods, r.payPer, false, true) +\n\n    '<label class=\"lbl\">Бонусы и премии</label>'+\n    chips('bonHas', ['да','нет','не знаю'], r.bonHas, false) +\n    '<div id=\"bonBox\" class=\"'+(r.bonHas==='да'?'':'hidden')+'\">'+\n      '<label class=\"lbl\">Размер бонуса</label>'+\n      '<input id=\"fBonSize\" inputmode=\"decimal\" placeholder=\"Например: 20 или 3000\" value=\"'+esc(r.bonSize)+'\">'+\n      '<div style=\"height:8px\"></div>'+ chips('bonType', ref.bonusTypes, r.bonType, false) +\n      '<div style=\"height:6px\"></div>'+ chips('bonPer', ref.bonusPeriods, r.bonPer, false) +\n    '</div>'+\n\n    '<label class=\"lbl\">Льготы и соцпакет</label>'+\n    chips('benefits', S.data.benefits || [], r.benefits, true) +\n\n    '<label class=\"lbl\">Прочие выплаты (необязательно)</label>'+\n    '<input id=\"fExtra\" placeholder=\"13-я зарплата, доплата за стаж…\" value=\"'+esc(r.extra)+'\">'+\n\n    '<label class=\"lbl\">Откуда данные</label>'+ chips('source', ref.sources, r.source, false) +\n    '<label class=\"lbl\">Насколько данные надёжны</label>'+ chips('trust', ref.trust, r.trust, false) +\n\n    '<label class=\"lbl\">Комментарий</label>'+\n    '<textarea id=\"fNote\">'+esc(r.note)+'</textarea>'+\n\n    '<div style=\"height:16px\"></div>'+\n    '<button id=\"fGo\" class=\"btn-primary\">'+(isNew?'Добавить':'Сохранить изменения')+'</button>'+\n    '<div style=\"height:10px\"></div></div>';\n\n  document.body.appendChild(el);\n\n  var coSel = el.querySelector('#fCo'), coOther = el.querySelector('#fCoOther');\n  coSel.onchange = function(){\n    var other = this.value === '__other__';\n    coOther.classList.toggle('hidden', !other);\n    if(other) coOther.focus();\n  };\n\n  // Должности — строгий выбор из штатки, с поиском.\n  // «У нас» — только должности своего подразделения, добавление пишется туда же.\n  // «У конкурента» — весь холдинг: у них своя штатка, нашей её ограничивать нельзя.\n  var bindPick = function(id, field, opt){\n    var btn = el.querySelector('#'+id);\n    btn.onclick = function(){\n      openPicker({\n        title: opt.title,\n        list: opt.list(),\n        wide: opt.wide ? opt.wide() : null,\n        wideLabel: opt.wideLabel,\n        addUnit: opt.addUnit ? S.unit : null,\n        value: r[field],\n        onPick: function(v){\n          r[field] = v;\n          btn.querySelector('span').textContent = v;\n          btn.querySelector('span').className = '';\n          btn.classList.remove('need');\n        }\n      });\n    };\n  };\n  bindPick('fPosOur', 'posOur', {\n    title: 'Должность у нас',\n    list: function(){ return S.data.positions || []; },\n    wide: function(){ return S.data.positionsAll || []; },\n    wideLabel: 'Показать все должности холдинга',\n    addUnit: true\n  });\n  bindPick('fPosTheir', 'posTheir', {\n    title: 'Должность у конкурента',\n    list: function(){ return S.data.positionsAll || []; }\n  });\n\n  el.addEventListener('click', function(e){\n    if(e.target === el || e.target.dataset.x){ el.remove(); return; }\n    var b = e.target.closest('.chips button');\n    if(!b) return;\n    var box = b.parentNode, act = b.dataset.act, v = b.dataset.v;\n    if(box.dataset.multi){\n      var k = r.benefits.indexOf(v);\n      if(k >= 0) r.benefits.splice(k,1); else r.benefits.push(v);\n      b.classList.toggle('on', k < 0);\n    } else {\n      // обязательные группы (валюта, период оклада) снять нельзя — только переключить\n      r[act] = (r[act] === v && !box.dataset.req) ? '' : v;\n      box.querySelectorAll('button').forEach(function(x){ x.classList.toggle('on', x.dataset.v === r[act]); });\n      if(act === 'bonHas') el.querySelector('#bonBox').classList.toggle('hidden', r.bonHas !== 'да');\n    }\n  });\n\n  el.querySelector('#fGo').onclick = function(){\n    var co = coSel.value === '__other__' ? coOther.value.trim() : coSel.value;\n    if(!co){ toast('Выберите или впишите компанию'); return; }\n    if(!r.posOur){\n      toast('Выберите должность у нас');\n      el.querySelector('#fPosOur').classList.add('need');\n      el.querySelector('#fPosOur').scrollIntoView({block:'center'});\n      return;\n    }\n\n    r.company   = co;\n    r.grade     = el.querySelector('#fGrade').value.trim();\n    r.payFrom   = el.querySelector('#fFrom').value.trim();\n    r.payTo     = el.querySelector('#fTo').value.trim();\n    r.bonSize   = el.querySelector('#fBonSize').value.trim();\n    r.extra     = el.querySelector('#fExtra').value.trim();\n    r.note      = el.querySelector('#fNote').value.trim();\n    if(r.bonHas !== 'да'){ r.bonSize=''; r.bonType=''; r.bonPer=''; }\n\n    if(isNew){ r.id = uid(); S.surveys.push(r); }\n    else { S.surveys[i] = r; }\n\n    el.remove();\n    markDirty();\n    renderUnit();\n    toast(isNew ? 'Запись добавлена. Не забудьте «Сохранить».' : 'Изменено. Не забудьте «Сохранить».');\n  };\n\n  setTimeout(function(){ el.querySelector('.sheet-in').scrollTop = 0; }, 30);\n}\n\n// ═══════════════════════════════════════════════════════════\n// ОБЩЕЕ: черновик, прогресс\n// ═══════════════════════════════════════════════════════════\nfunction markDirty(){\n  if(S.ro) return;\n  S.dirty = true;\n  store.set(LS_DRAFT+S.unit, JSON.stringify({\n    rows:S.rows, added:S.added, surveys:S.surveys, removed:S.removed, note:S.note }));\n}\n\nfunction updateProgress(){\n  var c = counts();\n\n  if(S.tab === 'comp'){\n    $('progT').textContent = c.done + ' из ' + c.all;\n    if(c.ask){\n      $('progS').className = 'ask';\n      $('progS').textContent = 'уточнить: ' + c.ask;\n    } else {\n      $('progS').className = '';\n      $('progS').textContent = (c.all && c.done === c.all) ? 'всё проверено' : 'проверено компаний';\n    }\n  } else {\n    // Ориентир — закрытые должности штатки, а не число записей:\n    // так у человека виден финиш, а не бесконечный список.\n    var g = survGroups();\n    if(g.groups.length){\n      var closed = g.groups.filter(function(x){ return x.items.length; }).length;\n      $('progT').textContent = closed + ' из ' + g.groups.length;\n      $('progS').className = '';\n      $('progS').textContent = (closed === g.groups.length) ? 'все должности закрыты' : 'должностей закрыто';\n    } else {\n      $('progT').textContent = S.surveys.length + (S.removed.length ? ' (−'+S.removed.length+')' : '');\n      $('progS').className = '';\n      $('progS').textContent = 'записей по должностям';\n    }\n  }\n\n  // счётчики на вкладках должны меняться сразу, а не после сохранения\n  var t1 = document.querySelector('.tabs button[data-tab=\"comp\"]');\n  var t2 = document.querySelector('.tabs button[data-tab=\"survey\"]');\n  if(t1){\n    t1.innerHTML = '<small>Шаг 1</small>Конкуренты · ' + c.done + '/' + c.all +\n      (c.ask ? ' <span style=\"color:var(--warn)\">?'+c.ask+'</span>' : '');\n    t1.classList.toggle('done', c.all > 0 && c.done === c.all);\n  }\n  if(t2){\n    t2.innerHTML = '<small>Шаг 2</small>Данные по рынку · ' + svLabel();\n    t2.classList.toggle('done', S.surveys.length > 0);\n  }\n\n  $('btnSave').classList.toggle('hidden', S.ro);\n  $('btnSave').textContent = 'Сохранить';\n}\n\n// ═══════════════════════════════════════════════════════════\n// ДОБАВЛЕНИЕ КОМПАНИИ-КОНКУРЕНТА\n// ═══════════════════════════════════════════════════════════\nfunction openAddSheet(){\n  var picked = { type:'', prio:'', seg:'', region:'' };\n\n  var el = document.createElement('div');\n  el.className = 'sheet';\n  el.innerHTML = '<div class=\"sheet-in\">'+\n    '<div class=\"sheet-hd\"><b>Добавить компанию</b>'+\n      '<button class=\"btn-ghost\" data-x=\"1\">Закрыть</button></div>'+\n    '<div id=\"addWarn\"></div>'+\n    '<label class=\"lbl\">Название компании</label>'+\n    '<input id=\"addName\" placeholder=\"Начните вводить…\" autocomplete=\"off\">'+\n    '<div id=\"addSug\"></div>'+\n    '<label class=\"lbl\">Тип конкурента</label>'+ chips('type', S.data.ref.types, '', false) +\n    '<label class=\"lbl\">Приоритет</label>'+ chips('prio', S.data.ref.priorities, '', false) +\n    '<label class=\"lbl\">Сегмент</label>'+ pickField('addSeg', '', 'Выберите сегмент', false) +\n    '<label class=\"lbl\">Регион</label>'+ pickField('addReg', '', 'Выберите регион', false) +\n    '<label class=\"lbl\">Комментарий</label><textarea id=\"addNote\"></textarea>'+\n    '<div style=\"height:14px\"></div>'+\n    '<button id=\"addGo\" class=\"btn-primary\">Добавить в список</button></div>';\n  document.body.appendChild(el);\n\n  // Сегмент и регион — из справочника, чтобы «Худжанд», «Худжанд (ГО)» и «худжанд»\n  // не расползались по таблице тремя разными значениями\n  var bindRef = function(id, field, title, block, list){\n    var btn = el.querySelector('#'+id);\n    btn.onclick = function(){\n      openPicker({\n        title: title, block: block, list: list(), value: picked[field],\n        onPick: function(v){\n          picked[field] = v;\n          btn.querySelector('span').textContent = v;\n          btn.querySelector('span').className = '';\n        }\n      });\n    };\n  };\n  bindRef('addSeg', 'seg', 'Сегмент', 'segments', function(){ return S.data.segments || []; });\n  bindRef('addReg', 'region', 'Регион присутствия', 'regions', function(){ return S.data.regions || []; });\n\n  el.addEventListener('click', function(e){\n    if(e.target === el || e.target.dataset.x){ el.remove(); return; }\n    var b = e.target.closest('.chips button');\n    if(!b) return;\n    var act = b.dataset.act;\n    picked[act] = (picked[act] === b.dataset.v) ? '' : b.dataset.v;\n    b.parentNode.querySelectorAll('button').forEach(function(x){\n      x.classList.toggle('on', x.dataset.v === picked[act]); });\n  });\n\n  var nameEl = el.querySelector('#addName');\n  nameEl.oninput = function(){\n    var q = this.value.trim().toLowerCase();\n    var w = el.querySelector('#addWarn'); w.innerHTML = '';\n    if(q.length >= 2){\n      var bad = S.data.banned.filter(function(b){ return b.name.toLowerCase().indexOf(q) >= 0; });\n      if(bad.length) w.innerHTML = '<div class=\"note\">«'+esc(bad[0].name)+'» — '+esc(bad[0].reason)+\n        '. Эту компанию включать в обзор нельзя.</div>';\n    }\n    var box = el.querySelector('#addSug');\n    if(q.length < 2){ box.innerHTML = ''; return; }\n    var hit = S.data.companies.filter(function(c){ return c.name.toLowerCase().indexOf(q) >= 0; }).slice(0,7);\n    box.innerHTML = hit.length ? '<div class=\"sug\">'+hit.map(function(c){\n      return '<div data-n=\"'+esc(c.name)+'\" data-s=\"'+esc(c.seg)+'\" data-r=\"'+esc(c.region)+'\">'+\n        esc(c.name)+'<small>'+esc([c.seg,c.region].filter(String).join(' · '))+'</small></div>'; }).join('')+'</div>' : '';\n    box.querySelectorAll('[data-n]').forEach(function(d){\n      d.onclick = function(){\n        nameEl.value = d.dataset.n;\n        if(d.dataset.s){\n          picked.seg = d.dataset.s;\n          var s = el.querySelector('#addSeg span');\n          s.textContent = d.dataset.s; s.className = '';\n        }\n        if(d.dataset.r){\n          picked.region = d.dataset.r;\n          var g = el.querySelector('#addReg span');\n          g.textContent = d.dataset.r; g.className = '';\n        }\n        box.innerHTML = '';\n      };\n    });\n  };\n\n  el.querySelector('#addGo').onclick = function(){\n    var name = nameEl.value.trim();\n    if(!name){ toast('Введите название компании'); return; }\n    var dup = S.rows.concat(S.added).some(function(r){\n      return r.company.toLowerCase() === name.toLowerCase(); });\n    if(dup){ toast('Такая компания уже есть в списке'); return; }\n    S.added.push({\n      id:'', unit:S.unit, company:name, type:picked.type, prio:picked.prio,\n      seg: picked.seg,\n      region: picked.region,\n      note: el.querySelector('#addNote').value.trim(),\n      status:'', src:'', actual:'актуально'\n    });\n    el.remove();\n    markDirty();\n    renderUnit();\n    toast('Компания добавлена. Не забудьте сохранить.');\n  };\n  setTimeout(function(){ nameEl.focus(); }, 60);\n}\n\n// ═══════════════════════════════════════════════════════════\n// СОХРАНЕНИЕ\n// ═══════════════════════════════════════════════════════════\n$('btnSave').onclick = function(){ save(false); };\n\nfunction save(submit){\n  if(S.saving || S.ro) return;\n  if(!submit){ doSave(false); return; }\n\n  var c = counts();\n  var q = null;\n  if(c.left){\n    q = { html: 'Не отмечено компаний: <b>'+c.left+'</b>.' +\n                (c.ask ? '\\nЕщё <b>'+c.ask+'</b> отложено на уточнение — они тоже не считаются проверенными.' : '') };\n  } else if(c.ask){\n    q = { html: 'Компаний на уточнении: <b>'+c.ask+'</b>.\\n' +\n                'Они не считаются проверенными — вопрос по ним ещё открыт.' };\n  }\n  if(!q){ doSave(true); return; }\n\n  ask({\n    title: 'Отправить как готовое?',\n    html: q.html,\n    ok: 'Всё равно отправить',\n    cancel: 'Вернуться'\n  }).then(function(yes){ if(yes) doSave(true); });\n}\n\nfunction doSave(submit){\n  if(S.saving || S.ro) return;\n  S.saving = true;\n  $('btnSave').disabled = true;\n  $('btnSave').textContent = 'Сохраняем…';\n\n  var unitAtSave = S.unit;\n\n  // Обе вкладки сохраняются вместе — человек не должен думать, где он находится\n  var p1 = call('apiSave', S.token, {\n    unit: unitAtSave, rows: S.rows, added: S.added, note: S.note, submit: !!submit });\n\n  var needSurvey = S.surveys.length > 0 || S.removed.length > 0;\n  var p2 = needSurvey\n    ? call('apiSaveSurvey', S.token, { unit: unitAtSave, upsert: S.surveys, remove: S.removed })\n    : Promise.resolve({ ok:true, newIds:[], added:0, updated:0, removed:0 });\n\n  Promise.all([p1, p2]).then(function(res){\n    S.saving = false;\n    $('btnSave').disabled = false;\n    $('btnSave').textContent = 'Сохранить';\n\n    var a = res[0], b = res[1];\n    if(!a || !a.ok || !b || !b.ok){\n      var msg = (a && !a.ok && a.error) || (b && !b.ok && b.error) || 'Не удалось сохранить';\n      toast(msg);\n      if(msg.indexOf('Сессия') === 0){\n        store.del(LS_TOKEN);\n        setTimeout(function(){ location.reload(); }, 1600);\n      }\n      return;\n    }\n\n    S.dirty = false;\n    store.del(LS_DRAFT + unitAtSave);\n\n    // Конкуренты: добавленные получили ID — переносим в основной список\n    S.added.forEach(function(x, k){\n      x.id = (a.newIds && a.newIds[k]) || x.id;\n      if(x.id){ S.rows.push(x); S.data.rows.push(x); }\n    });\n    S.added = [];\n    syncCache(S.rows, S.data.rows);\n\n    // Обзор: newIds идёт в том же порядке, что и отправленный upsert\n    (b.newIds || []).forEach(function(id, k){\n      if(id && S.surveys[k]) S.surveys[k].id = id;\n    });\n    S.removed = [];\n    S.data.surveys = S.data.surveys.filter(function(x){ return x.unit !== unitAtSave; })\n      .concat(S.surveys.map(function(x){ return JSON.parse(JSON.stringify(x)); }));\n\n    var u = S.data.units.filter(function(x){ return x.unit === unitAtSave; })[0];\n    if(u){\n      var after = counts();\n      u.total = after.all;\n      u.done = after.done;\n      u.ask = after.ask;\n      u.surveys = S.surveys.length;\n    }\n\n    toast(submit ? 'Отправлено. Спасибо!' : 'Сохранено в ' + a.at);\n    if(submit) setTimeout(renderUnits, 900);\n    else renderUnit();\n  }).catch(function(){\n    S.saving = false;\n    $('btnSave').disabled = false;\n    $('btnSave').textContent = 'Сохранить';\n    toast('Нет связи. Черновик сохранён на устройстве — попробуйте позже.');\n  });\n}\n\nfunction syncCache(local, cache){\n  var byId = {};\n  local.forEach(function(x){ if(x.id) byId[x.id] = x; });\n  cache.forEach(function(x){ if(byId[x.id] && byId[x.id] !== x) Object.assign(x, byId[x.id]); });\n}\n\nwindow.addEventListener('beforeunload', function(e){\n  if(S.dirty){ e.preventDefault(); e.returnValue = ''; }\n});\n\n// ═══════════════════════════════════════════════════════════\n// АНАЛИТИЧЕСКИЙ ДАШБОРД (C&B, РУКОВОДСТВО, HR BP)\n// ═══════════════════════════════════════════════════════════\nfunction openDashboard(){\n  S.appView = 'dashboard';\n  S.unit = null;\n  renderTopNav();\n  setTop('📊 Аналитический Дашборд', userLabel(), false);\n  $('bar').classList.add('hidden');\n  $('body').onclick = null;\n  $('body').innerHTML = '<div class=\"sp\"><i></i> Загрузка аналитики рынка…</div>';\n\n  call('apiCBDashboardExtended', S.token, S.dashFilters).then(function(r){\n    if(!r || !r.ok){\n      $('body').innerHTML = '<div class=\"err\">'+esc((r&&r.error)||'Не удалось загрузить данные дашборда')+'</div>';\n      return;\n    }\n    S.dashData = r;\n    renderDashboard();\n  }).catch(function(){\n    $('body').innerHTML = '<div class=\"err\">Нет связи с сервером. Попробуйте обновить.</div>';\n  });\n}\n\nfunction renderDashboard(){\n  if(!S.dashData) return;\n  var d = S.dashData;\n  var sm = d.summary || {};\n\n  // 1. KPI Карточки\n  var h = '<div class=\"kpi-grid\">'+\n    '<div class=\"kpi-card\">'+\n      '<div class=\"kpi-t\">Охват отделов</div>'+\n      '<div class=\"kpi-v\">'+sm.completedDivisions+' <span style=\"font-size:15px;color:var(--muted)\">/ '+sm.totalDivisions+'</span></div>'+\n      '<div class=\"kpi-s\">Завершено <b>'+sm.divCompletionPct+'%</b></div>'+\n    '</div>'+\n    '<div class=\"kpi-card\">'+\n      '<div class=\"kpi-t\">Проверено связей</div>'+\n      '<div class=\"kpi-v\">'+sm.checkedCompetitorLinks+' <span style=\"font-size:15px;color:var(--muted)\">/ '+sm.totalCompetitorLinks+'</span></div>'+\n      '<div class=\"kpi-s\">Актуализировано <b>'+sm.compCompletionPct+'%</b></div>'+\n    '</div>'+\n    '<div class=\"kpi-card\">'+\n      '<div class=\"kpi-t\">Записей по рынку</div>'+\n      '<div class=\"kpi-v\">'+sm.totalSurveyRecords+'</div>'+\n      '<div class=\"kpi-s\">С окладом: <b>'+sm.recordsWithSalary+'</b></div>'+\n    '</div>'+\n    '<div class=\"kpi-card\">'+\n      '<div class=\"kpi-t\">Должностей с вилкой</div>'+\n      '<div class=\"kpi-v\">'+sm.positionsCount+'</div>'+\n      '<div class=\"kpi-s\">Сформировано перцентилей</div>'+\n    '</div>'+\n  '</div>';\n\n  // 2. Вкладки Дашборда\n  var tabs = [\n    { id:'salaries', label:'💰 Зарплатные вилки' },\n    { id:'progress', label:'🎯 Прогресс по HR BP' },\n    { id:'benefits', label:'🎁 Льготы и Бонусы' }\n  ];\n  h += '<div class=\"sub-tabs\">'+ tabs.map(function(t){\n    var on = S.dashTab === t.id ? ' on' : '';\n    return '<button class=\"sub-tab'+on+'\" data-dtab=\"'+t.id+'\">'+esc(t.label)+'</button>';\n  }).join('') +'</div>';\n\n  // 3. Панель фильтров\n  var allDirs = (d.dirProgress || []).map(function(x){ return x.dir; }).filter(function(x){ return x && x !== 'Без направления'; });\n  var allHrbps = (d.hrbpProgress || []).map(function(x){ return x.hrbp; }).filter(function(x){ return x && x !== 'Не назначен'; });\n\n  h += '<div class=\"dash-filters\">'+\n    '<input id=\"dashSearch\" placeholder=\"🔍 Поиск должности или компании…\" value=\"'+esc(S.dashFilters.search)+'\">'+\n    '<select id=\"dashDir\">'+\n      '<option value=\"\">Все направления</option>'+\n      allDirs.map(function(dir){\n        return '<option value=\"'+esc(dir)+'\"'+(S.dashFilters.dir===dir?' selected':'')+'>'+esc(dir)+'</option>';\n      }).join('')+\n    '</select>'+\n    '<select id=\"dashHrbp\">'+\n      '<option value=\"\">Все HR BP</option>'+\n      allHrbps.map(function(h){\n        return '<option value=\"'+esc(h)+'\"'+(S.dashFilters.hrbp===h?' selected':'')+'>'+esc(h)+'</option>';\n      }).join('')+\n    '</select>'+\n  '</div>';\n\n  h += '<div class=\"dash-actions\">'+\n    '<button id=\"btnDashReset\" class=\"btn-ghost\" style=\"border:1px solid var(--line);min-height:36px\">Сбросить фильтры</button>'+\n    '<button id=\"btnDashExport\" class=\"btn-line\" style=\"width:auto;margin-left:auto;min-height:36px;color:var(--accent)\">📥 Экспорт в CSV</button>'+\n  '</div>';\n\n  // 4. Контент выбранной вкладки\n  if(S.dashTab === 'salaries'){\n    h += renderSalariesTab(d.positions || []);\n  } else if(S.dashTab === 'progress'){\n    h += renderProgressTab(d.hrbpProgress || [], d.dirProgress || []);\n  } else if(S.dashTab === 'benefits'){\n    h += renderBenefitsTab(d.topBenefits || [], d.bonuses || {}, d.topCompetitors || []);\n  }\n\n  $('body').innerHTML = h;\n\n  // Слушатели событий дашборда\n  $('body').querySelectorAll('button[data-dtab]').forEach(function(btn){\n    btn.onclick = function(){\n      S.dashTab = this.dataset.dtab;\n      renderDashboard();\n    };\n  });\n\n  var searchIn = $('dashSearch');\n  var timer = null;\n  searchIn.oninput = function(){\n    clearTimeout(timer);\n    timer = setTimeout(function(){\n      S.dashFilters.search = searchIn.value.trim();\n      openDashboard();\n    }, 400);\n  };\n\n  $('dashDir').onchange = function(){\n    S.dashFilters.dir = this.value;\n    openDashboard();\n  };\n\n  $('dashHrbp').onchange = function(){\n    S.dashFilters.hrbp = this.value;\n    openDashboard();\n  };\n\n  $('btnDashReset').onclick = function(){\n    S.dashFilters = { dir:'', hrbp:'', search:'' };\n    openDashboard();\n  };\n\n  $('btnDashExport').onclick = exportDashboardCSV;\n}\n\nfunction renderSalariesTab(positions){\n  if(!positions.length){\n    return '<div class=\"empty\">По заданным условиям должностей не найдено</div>';\n  }\n\n  var h = '<div class=\"sec-title\">Зарплатные вилки по должностям ('+positions.length+')</div>';\n\n  h += positions.map(function(pos, idx){\n    var maxVal = Math.max(pos.max, 1);\n    var p25Pct = pos.min > 0 ? Math.round((pos.p25 / maxVal) * 100) : 0;\n    var p75Pct = pos.min > 0 ? Math.round((pos.p75 / maxVal) * 100) : 0;\n    var medPct = pos.min > 0 ? Math.round((pos.median / maxVal) * 100) : 0;\n    var wPct = Math.max(p75Pct - p25Pct, 4);\n\n    var cardId = 'posCard_' + idx;\n    var bodyId = 'posBody_' + idx;\n\n    var forkVisual = pos.min > 0\n      ? '<div class=\"fork-nums\">'+\n          '<span>Мин: <b>'+pos.min.toLocaleString('ru-RU')+'</b></span>'+\n          '<span>P25: <b>'+pos.p25.toLocaleString('ru-RU')+'</b></span>'+\n          '<span class=\"f-med\">Медиана: <b>'+pos.median.toLocaleString('ru-RU')+'</b></span>'+\n          '<span>P75: <b>'+pos.p75.toLocaleString('ru-RU')+'</b></span>'+\n          '<span>Макс: <b>'+pos.max.toLocaleString('ru-RU')+'</b></span>'+\n        '</div>'+\n        '<div class=\"fork-track-wrap\">'+\n          '<div class=\"fork-track-p25-p75\" style=\"left:'+p25Pct+'%;width:'+wPct+'%\"></div>'+\n          '<div class=\"fork-track-med\" style=\"left:'+medPct+'%\"></div>'+\n        '</div>'\n      : '<div style=\"font-size:12.5px;color:var(--muted);margin:6px 0\">Нет числовых данных по окладу</div>';\n\n    var coList = (pos.companies || []).map(function(c){\n      var payStr = (c.pFrom || c.pTo)\n        ? (c.pFrom ? c.pFrom.toLocaleString('ru-RU') : '—') + ' … ' + (c.pTo ? c.pTo.toLocaleString('ru-RU') : '—') + ' ' + esc(c.cur)\n        : 'не указан';\n      var bonStr = c.bonHas === 'да' ? (esc(c.bonType || 'Бонус') + (c.bonSize ? ': ' + esc(c.bonSize) : '')) : (c.bonHas === 'нет' ? 'Без бонуса' : '—');\n      var bList = (c.benefits || []).map(function(b){ return '<span class=\"pill p-ok\" style=\"font-size:10.5px;margin-right:3px\">'+esc(b)+'</span>'; }).join('');\n\n      return '<tr>'+\n        '<td><b>'+esc(c.company)+'</b><br><small style=\"color:var(--muted)\">'+esc(c.unit)+'</small></td>'+\n        '<td>'+payStr+'</td>'+\n        '<td>'+bonStr+'</td>'+\n        '<td>'+(bList || '<span style=\"color:var(--muted)\">—</span>')+'</td>'+\n        '<td><small style=\"color:var(--muted)\">'+esc(c.note || '—')+'</small></td>'+\n      '</tr>';\n    }).join('');\n\n    return '<div class=\"fork-box\" id=\"'+cardId+'\">'+\n      '<div class=\"fork-hd\" onclick=\"togglePosBody(\\''+bodyId+'\\')\">'+\n        '<div class=\"fork-pos\">'+esc(pos.pos)+'</div>'+\n        '<div class=\"fork-cnt\">'+pos.count+' '+declOfNum(pos.count, ['запись','записи','записей'])+'</div>'+\n        (pos.forkSpreadPct ? '<div class=\"pill p-mid\">размах +'+pos.forkSpreadPct+'%</div>' : '')+\n        '<div style=\"font-size:18px;color:var(--muted)\">▾</div>'+\n      '</div>'+\n      forkVisual +\n      '<div id=\"'+bodyId+'\" class=\"fork-body hidden\">'+\n        '<div class=\"tblwrap\">'+\n          '<table class=\"co-tbl\">'+\n            '<tr><th>Компания / Отдел</th><th>Вилка оклада</th><th>Премии</th><th>Льготы</th><th>Примечание</th></tr>'+\n            coList +\n          '</table>'+\n        '</div>'+\n      '</div>'+\n    '</div>';\n  }).join('');\n\n  return h;\n}\n\nfunction togglePosBody(id){\n  var el = $(id);\n  if(el) el.classList.toggle('hidden');\n}\n\nfunction renderProgressTab(hrbpList, dirList){\n  var h = '<div class=\"sec-title\">Прогресс сбора по HR BP</div>';\n\n  if(S.data && (S.data.user.role === 'admin' || S.data.user.role === 'cb')){\n    h += '<div style=\"margin-bottom:14px\">'+\n      '<button id=\"btnMassReminder\" class=\"btn-primary\" style=\"width:auto;font-size:13.5px;min-height:38px\">'+\n        '📢 Напомнить всем должникам в Telegram'+\n      '</button>'+\n    '</div>';\n  }\n\n  h += hrbpList.map(function(hItem){\n    var isDone = hItem.pct >= 100;\n    var cls = isDone ? 'p-ok' : (hItem.pct > 0 ? 'p-mid' : 'p-no');\n    return '<div class=\"prog-row\">'+\n      '<div class=\"prog-hd\">'+\n        '<span>'+esc(hItem.hrbp)+'</span>'+\n        '<span class=\"pill '+cls+'\">'+hItem.pct+'%</span>'+\n      '</div>'+\n      '<div class=\"prog-bar-bg\">'+\n        '<div class=\"prog-bar-fill\" style=\"width:'+hItem.pct+'%;background:'+(isDone?'var(--ok)':'var(--accent)')+'\"></div>'+\n      '</div>'+\n      '<div class=\"prog-sub\">'+\n        '<span>Подразделений: <b>'+hItem.unitsDone+' / '+hItem.unitsTotal+'</b></span>'+\n        '<span>Связей: <b>'+hItem.compDone+' / '+hItem.compTotal+'</b> · Анкет: <b>'+hItem.surveysTotal+'</b></span>'+\n      '</div>'+\n    '</div>';\n  }).join('');\n\n  h += '<div class=\"sec-title\" style=\"margin-top:24px\">Прогресс сбора по Дирекциям</div>';\n  h += dirList.map(function(dItem){\n    var isDone = dItem.pct >= 100;\n    var cls = isDone ? 'p-ok' : (dItem.pct > 0 ? 'p-mid' : 'p-no');\n    return '<div class=\"prog-row\">'+\n      '<div class=\"prog-hd\">'+\n        '<span>'+esc(dItem.dir)+'</span>'+\n        '<span class=\"pill '+cls+'\">'+dItem.pct+'%</span>'+\n      '</div>'+\n      '<div class=\"prog-bar-bg\">'+\n        '<div class=\"prog-bar-fill\" style=\"width:'+dItem.pct+'%;background:'+(isDone?'var(--ok)':'var(--accent)')+'\"></div>'+\n      '</div>'+\n      '<div class=\"prog-sub\">'+\n        '<span>Отделов: <b>'+dItem.unitsDone+' / '+dItem.unitsTotal+'</b></span>'+\n        '<span>Связей: <b>'+dItem.compDone+' / '+dItem.compTotal+'</b></span>'+\n      '</div>'+\n    '</div>';\n  }).join('');\n\n  setTimeout(function(){\n    var b = $('btnMassReminder');\n    if(b){\n      b.onclick = function(){\n        ask({\n          title: 'Массовое напоминание в Telegram',\n          html: 'Бот отправит персональные уведомления всем ответственным и руководителям, у которых остались незаполненные подразделения.',\n          ok: 'Отправить напоминания'\n        }).then(function(yes){\n          if(!yes) return;\n          b.disabled = true; b.textContent = 'Отправляем…';\n          call('apiSendMassReminder', S.token).then(function(res){\n            b.disabled = false; b.textContent = '📢 Напомнить всем должникам в Telegram';\n            if(res && res.ok){\n              toast('Успешно отправлено напоминаний: ' + res.sent);\n            } else {\n              toast((res && res.error) || 'Ошибка отправки');\n            }\n          }).catch(function(){\n            b.disabled = false; b.textContent = '📢 Напомнить всем должникам в Telegram';\n            toast('Нет связи');\n          });\n        });\n      };\n    }\n  }, 100);\n\n  return h;\n}\n\nfunction renderBenefitsTab(benefits, bonuses, topComps){\n  var h = '<div class=\"sec-title\">Рейтинг популярности льгот и бенефитов</div>';\n\n  if(!benefits.length){\n    h += '<div class=\"empty\">Нет данных о льготах</div>';\n  } else {\n    h += benefits.map(function(b){\n      return '<div class=\"prog-row\">'+\n        '<div class=\"prog-hd\">'+\n          '<span>'+esc(b.name)+'</span>'+\n          '<span class=\"pill p-ok\">'+b.pct+'%</span>'+\n        '</div>'+\n        '<div class=\"prog-bar-bg\">'+\n          '<div class=\"prog-bar-fill\" style=\"width:'+b.pct+'%\"></div>'+\n        '</div>'+\n        '<div class=\"prog-sub\">'+\n          '<span>Упоминаний: <b>'+b.count+'</b></span>'+\n          '<span>Охват рынка: <b>'+b.pct+'%</b></span>'+\n        '</div>'+\n      '</div>';\n    }).join('');\n  }\n\n  // Бонусы\n  h += '<div class=\"sec-title\" style=\"margin-top:24px\">Структура премирования и бонусов</div>';\n  var bTotal = (bonuses.hasBonus || 0) + (bonuses.noBonus || 0) + (bonuses.unknown || 0);\n  var hasPct = bTotal ? Math.round((bonuses.hasBonus / bTotal) * 100) : 0;\n  var noPct = bTotal ? Math.round((bonuses.noBonus / bTotal) * 100) : 0;\n\n  h += '<div class=\"card\" style=\"margin-bottom:16px\">'+\n    '<div style=\"font-weight:700;font-size:15px;margin-bottom:8px\">Наличие премий в компаниях</div>'+\n    '<div class=\"fork-nums\">'+\n      '<span style=\"color:var(--ok)\">Премии предусмотрены: <b>'+(bonuses.hasBonus||0)+' ('+hasPct+'%)</b></span>'+\n      '<span style=\"color:var(--no)\">Без премий: <b>'+(bonuses.noBonus||0)+' ('+noPct+'%)</b></span>'+\n    '</div>'+\n    '<div class=\"prog-bar-bg\" style=\"height:12px;margin:8px 0\">'+\n      '<div class=\"prog-bar-fill\" style=\"width:'+hasPct+'%;background:var(--ok)\"></div>'+\n    '</div>'+\n  '</div>';\n\n  // Топ конкурентов\n  h += '<div class=\"sec-title\" style=\"margin-top:24px\">Топ упоминаемых компаний-конкурентов ('+topComps.length+')</div>';\n  h += '<div class=\"tblwrap\"><table class=\"co-tbl\">'+\n    '<tr><th>Компания</th><th>Количество записей в анкетах</th></tr>'+\n    topComps.map(function(c){\n      return '<tr><td><b>'+esc(c.company)+'</b></td><td>'+c.count+'</td></tr>';\n    }).join('')+\n  '</table></div>';\n\n  return h;\n}\n\nfunction exportDashboardCSV(){\n  if(!S.dashData || !S.dashData.positions || !S.dashData.positions.length){\n    toast('Нет данных для экспорта');\n    return;\n  }\n  var headers = ['Должность', 'Всего записей', 'С окладом', 'Мин (TJS)', '25% перцентиль (TJS)', 'Медиана (TJS)', '75% перцентиль (TJS)', 'Макс (TJS)', 'Среднее (TJS)', 'Размах вилки (%)'];\n  var rows = S.dashData.positions.map(function(p){\n    return [\n      '\"' + (p.pos || '').replace(/\"/g, '\"\"') + '\"',\n      p.count,\n      p.withSalaryCount,\n      p.min,\n      p.p25,\n      p.median,\n      p.p75,\n      p.max,\n      p.avg,\n      p.forkSpreadPct + '%'\n    ].join(';');\n  });\n\n  var csvContent = '\\uFEFF' + headers.join(';') + '\\n' + rows.join('\\n');\n  var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });\n  var url = URL.createObjectURL(blob);\n  var a = document.createElement('a');\n  a.href = url;\n  a.download = 'Обзор_рынка_зарплатные_вилки_C&B.csv';\n  document.body.appendChild(a);\n  a.click();\n  document.body.removeChild(a);\n  URL.revokeObjectURL(url);\n  toast('Файл отчёта CSV сформирован и скачан');\n}\n\nfunction declOfNum(n, titles){\n  return titles[(n%10===1 && n%100!==11) ? 0 : (n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20)) ? 1 : 2];\n}\n\n// ═══════════════════════════════════════════════════════════\n// ПАНЕЛЬ АДМИНИСТРАТОРА\n// ═══════════════════════════════════════════════════════════\nfunction openAdminPanel(){\n  S.appView = 'admin';\n  S.unit = null;\n  renderTopNav();\n  setTop('⚙️ Панель Администратора', userLabel(), false);\n  $('bar').classList.add('hidden');\n  $('body').onclick = null;\n  renderAdminPanel();\n}\n\nfunction renderAdminPanel(){\n  var tabs = [\n    { id:'users', label:'👥 Пользователи' },\n    { id:'divisions', label:'🏢 Оргструктура (326)' },\n    { id:'period', label:'⏱️ Период сбора' },\n    { id:'tools', label:'🛠️ Сервис и Журнал' }\n  ];\n\n  var h = '<div class=\"sub-tabs\">'+ tabs.map(function(t){\n    var on = S.adminTab === t.id ? ' on' : '';\n    return '<button class=\"sub-tab'+on+'\" data-atab=\"'+t.id+'\">'+esc(t.label)+'</button>';\n  }).join('') +'</div>';\n\n  h += '<div id=\"adminContent\"><div class=\"sp\"><i></i> Загрузка…</div></div>';\n  $('body').innerHTML = h;\n\n  $('body').querySelectorAll('button[data-atab]').forEach(function(btn){\n    btn.onclick = function(){\n      S.adminTab = this.dataset.atab;\n      renderAdminPanel();\n    };\n  });\n\n  if(S.adminTab === 'users') loadAdminUsers();\n  else if(S.adminTab === 'divisions') loadAdminDivisions();\n  else if(S.adminTab === 'period') renderAdminPeriod();\n  else if(S.adminTab === 'tools') renderAdminTools();\n}\n\n// ─── Вкладка: Пользователи ───\nfunction loadAdminUsers(){\n  call('apiAdminGetUsers', S.token).then(function(r){\n    if(!r || !r.ok){\n      $('adminContent').innerHTML = '<div class=\"err\">'+esc((r&&r.error)||'Ошибка загрузки пользователей')+'</div>';\n      return;\n    }\n    S.adminUsers = r.users || [];\n    renderAdminUsers();\n  }).catch(function(){\n    $('adminContent').innerHTML = '<div class=\"err\">Нет связи с сервером</div>';\n  });\n}\n\nfunction renderAdminUsers(){\n  var users = S.adminUsers || [];\n  var search = ($('uSearch') ? $('uSearch').value : '').toLowerCase();\n  var roleFilter = $('uRole') ? $('uRole').value : '';\n\n  var filtered = users.filter(function(u){\n    var matchSearch = !search || u.fio.toLowerCase().indexOf(search) >= 0 || u.login.toLowerCase().indexOf(search) >= 0;\n    var matchRole = !roleFilter || u.role === roleFilter;\n    return matchSearch && matchRole;\n  });\n\n  var h = '<div class=\"dash-filters\">'+\n    '<input id=\"uSearch\" placeholder=\"🔍 Поиск по ФИО или логину…\" value=\"'+esc(search)+'\">'+\n    '<select id=\"uRole\">'+\n      '<option value=\"\">Все роли ('+users.length+')</option>'+\n      '<option value=\"admin\"'+(roleFilter==='admin'?' selected':'')+'>Администраторы (admin)</option>'+\n      '<option value=\"cb\"'+(roleFilter==='cb'?' selected':'')+'>C&B Аналитики (cb)</option>'+\n      '<option value=\"hrbp\"'+(roleFilter==='hrbp'?' selected':'')+'>HR BP (hrbp)</option>'+\n      '<option value=\"dir_head\"'+(roleFilter==='dir_head'?' selected':'')+'>Руководители направлений</option>'+\n      '<option value=\"head\"'+(roleFilter==='head'?' selected':'')+'>Руководители отделов</option>'+\n      '<option value=\"user\"'+(roleFilter==='user'?' selected':'')+'>Сотрудники (user)</option>'+\n    '</select>'+\n  '</div>';\n\n  h += '<div style=\"margin-bottom:14px\">'+\n    '<button id=\"btnAddUser\" class=\"btn-primary\" style=\"width:auto;min-height:38px;font-size:13.5px\">+ Добавить пользователя</button>'+\n  '</div>';\n\n  h += '<div class=\"sec-title\">Список пользователей ('+filtered.length+')</div>';\n\n  h += filtered.map(function(u){\n    var rBadge = 'b-user';\n    if(u.role === 'admin') rBadge = 'b-admin';\n    else if(u.role === 'cb') rBadge = 'b-cb';\n    else if(u.role === 'hrbp') rBadge = 'b-hrbp';\n    else if(u.role === 'dir_head' || u.role === 'head') rBadge = 'b-head';\n\n    return '<div class=\"u-card\" id=\"ucard_'+esc(u.login)+'\">'+\n      '<div class=\"u-hd\">'+\n        '<div class=\"u-fio\">'+esc(u.fio)+'</div>'+\n        '<div>'+\n          '<span class=\"badge '+rBadge+'\">'+esc(u.role)+'</span> '+\n          '<span class=\"badge '+(u.active?'b-active':'b-blocked')+'\">'+(u.active?'Активен':'Заблокирован')+'</span>'+\n        '</div>'+\n      '</div>'+\n      '<div class=\"u-meta\">'+\n        'Логин: <b>'+esc(u.login)+'</b>'+\n        (u.phone ? ' · Тел: '+esc(u.phone) : '') +\n        (u.hasTelegram ? ' · <span class=\"badge b-tg\">Telegram привязан</span>' : '') +\n        '<br>Подразделений: <b>'+(u.units?u.units.length:0)+'</b>'+\n        (u.lastIn ? ' · Вход: '+esc(u.lastIn) : '') +\n      '</div>'+\n      '<div class=\"u-acts\">'+\n        '<button class=\"btn-line\" onclick=\"openUserModal(\\''+esc(u.login)+'\\')\">✏️ Изменить</button>'+\n        '<button class=\"btn-line\" onclick=\"adminResetPwd(\\''+esc(u.login)+'\\')\">🔑 Сбросить пароль</button>'+\n        '<button class=\"btn-line '+(u.active?'btn-danger':'')+'\" onclick=\"adminToggleUser(\\''+esc(u.login)+'\\','+(!u.active)+')\">'+\n          (u.active ? '🚫 Заблокировать' : '✅ Активировать')+\n        '</button>'+\n      '</div>'+\n    '</div>';\n  }).join('');\n\n  $('adminContent').innerHTML = h;\n\n  $('uSearch').oninput = renderAdminUsers;\n  $('uRole').onchange = renderAdminUsers;\n  $('btnAddUser').onclick = function(){ openUserModal(null); };\n}\n\nfunction openUserModal(login){\n  var u = login ? (S.adminUsers || []).filter(function(x){ return x.login === login; })[0] : null;\n  var isEdit = !!u;\n\n  var userUnits = {};\n  if(u && u.units) u.units.forEach(function(un){ userUnits[un] = true; });\n\n  var el = document.createElement('div');\n  el.className = 'sheet';\n  el.innerHTML = '<div class=\"sheet-in\">'+\n    '<div class=\"sheet-hd\"><b>'+(isEdit ? 'Редактирование: ' + esc(u.fio) : 'Новый пользователь')+'</b>'+\n      '<button class=\"btn-ghost\" data-x=\"1\">Закрыть</button></div>'+\n    '<div id=\"uModalErr\" class=\"err hidden\"></div>'+\n    '<label class=\"lbl\" style=\"margin-top:4px\">ФИО *</label>'+\n    '<input id=\"umFio\" value=\"'+esc(u?u.fio:'')+'\" placeholder=\"Иванов Иван Иванович\">'+\n    '<label class=\"lbl\">Логин (оставьте пустым для автогенерации)</label>'+\n    '<input id=\"umLogin\" value=\"'+esc(u?u.login:'')+'\" placeholder=\"ivanov\" '+(isEdit?'readonly style=\"opacity:.7\"':'')+'>'+\n    '<label class=\"lbl\">Роль</label>'+\n    '<select id=\"umRole\">'+\n      '<option value=\"user\"'+(u&&u.role==='user'?' selected':'')+'>user — Сотрудник</option>'+\n      '<option value=\"head\"'+(u&&u.role==='head'?' selected':'')+'>head — Руководитель отдела</option>'+\n      '<option value=\"dir_head\"'+(u&&u.role==='dir_head'?' selected':'')+'>dir_head — Руководитель направления</option>'+\n      '<option value=\"hrbp\"'+(u&&u.role==='hrbp'?' selected':'')+'>hrbp — HR BP</option>'+\n      '<option value=\"cb\"'+(u&&u.role==='cb'?' selected':'')+'>cb — C&B Аналитик</option>'+\n      '<option value=\"admin\"'+(u&&u.role==='admin'?' selected':'')+'>admin — Администратор</option>'+\n    '</select>'+\n    '<label class=\"lbl\">Телефон (9 цифр для Telegram)</label>'+\n    '<input id=\"umPhone\" value=\"'+esc(u?u.phone:'')+'\" placeholder=\"992900000000\">'+\n    '<label class=\"lbl\">'+(isEdit?'Новый пароль (оставьте пустым, чтобы не менять)':'Пароль (оставьте пустым для автогенерации)')+'</label>'+\n    '<input id=\"umPwd\" type=\"text\" placeholder=\"пароль\">'+\n    '<div style=\"margin:14px 0 10px\">'+\n      '<label><input type=\"checkbox\" id=\"umActive\" '+(u&&!u.active?'':'checked')+'> Пользователь активен</label>'+\n    '</div>'+\n    '<div class=\"sec-title\" style=\"margin-top:14px\">Закрепленные подразделения</div>'+\n    '<input id=\"umUnitSearch\" placeholder=\"🔍 Фильтр подразделений…\">'+\n    '<div id=\"umUnitList\" style=\"max-height:180px;overflow:auto;border:1px solid var(--line);border-radius:10px;margin-top:6px;padding:6px\"></div>'+\n    '<div style=\"height:16px\"></div>'+\n    '<button id=\"umSave\" class=\"btn-primary\">Сохранить</button>'+\n  '</div>';\n\n  document.body.appendChild(el);\n\n  function drawUnits(){\n    var q = (el.querySelector('#umUnitSearch').value || '').toLowerCase();\n    var all = S.data.allUnits || [];\n    el.querySelector('#umUnitList').innerHTML = all.filter(function(x){\n      return !q || x.unit.toLowerCase().indexOf(q) >= 0 || x.dir.toLowerCase().indexOf(q) >= 0;\n    }).slice(0, 100).map(function(x){\n      return '<label class=\"pickrow\"><input type=\"checkbox\" data-u=\"'+esc(x.unit)+'\"'+\n        (userUnits[x.unit]?' checked':'')+'><span>'+esc(x.unit)+\n        '<br><small style=\"color:var(--muted)\">'+esc(x.dir)+'</small></span></label>';\n    }).join('') || '<p style=\"color:var(--muted);padding:8px\">Ничего не найдено</p>';\n  }\n  drawUnits();\n\n  el.querySelector('#umUnitSearch').oninput = drawUnits;\n  el.querySelector('#umUnitList').onchange = function(e){\n    if(e.target.dataset.u) userUnits[e.target.dataset.u] = e.target.checked;\n  };\n\n  el.addEventListener('click', function(e){\n    if(e.target === el || e.target.dataset.x) el.remove();\n  });\n\n  el.querySelector('#umSave').onclick = function(){\n    var fio = el.querySelector('#umFio').value.trim();\n    if(!fio){\n      var err = el.querySelector('#uModalErr');\n      err.textContent = 'Укажите ФИО'; err.classList.remove('hidden'); return;\n    }\n    var assignedUnits = Object.keys(userUnits).filter(function(k){ return userUnits[k]; });\n    var payload = {\n      fio: fio,\n      login: el.querySelector('#umLogin').value.trim(),\n      role: el.querySelector('#umRole').value,\n      phone: el.querySelector('#umPhone').value.trim(),\n      password: el.querySelector('#umPwd').value.trim(),\n      active: el.querySelector('#umActive').checked,\n      units: assignedUnits\n    };\n\n    var btn = this;\n    btn.disabled = true; btn.textContent = 'Сохраняем…';\n    call('apiAdminSaveUser', S.token, payload).then(function(res){\n      btn.disabled = false; btn.textContent = 'Сохранить';\n      if(res && res.ok){\n        el.remove();\n        toast('Пользователь сохранён');\n        loadAdminUsers();\n      } else {\n        var err = el.querySelector('#uModalErr');\n        err.textContent = (res && res.error) || 'Ошибка сохранения';\n        err.classList.remove('hidden');\n      }\n    }).catch(function(){\n      btn.disabled = false; btn.textContent = 'Сохранить';\n      toast('Нет связи');\n    });\n  };\n}\n\nfunction adminToggleUser(login, active){\n  ask({\n    title: (active ? 'Активировать' : 'Заблокировать') + ' пользователя?',\n    html: 'Пользователь: <b>' + esc(login) + '</b>',\n    ok: active ? 'Активировать' : 'Заблокировать',\n    danger: !active\n  }).then(function(yes){\n    if(!yes) return;\n    call('apiAdminToggleUser', S.token, login, active).then(function(res){\n      if(res && res.ok){\n        toast('Статус обновлён');\n        loadAdminUsers();\n      } else {\n        toast((res && res.error) || 'Ошибка');\n      }\n    });\n  });\n}\n\nfunction adminResetPwd(login){\n  ask({\n    title: 'Сбросить пароль пользователя?',\n    html: 'Для логина <b>'+esc(login)+'</b> будет сгенерирован новый пароль.',\n    ok: 'Сгенерировать пароль'\n  }).then(function(yes){\n    if(!yes) return;\n    call('apiAdminResetPassword', S.token, login).then(function(res){\n      if(res && res.ok){\n        ask({\n          title: 'Новый пароль выдан',\n          html: 'Логин: <b>'+esc(res.login)+'</b><br>Новый пароль: <b style=\"font-size:18px;color:var(--accent)\">'+esc(res.newPassword)+'</b><br><br>Передайте эти данные сотруднику.',\n          ok: 'Скопировано / Понятно'\n        });\n      } else {\n        toast((res && res.error) || 'Ошибка сброса');\n      }\n    });\n  });\n}\n\n// ─── Вкладка: Оргструктура ───\nfunction loadAdminDivisions(){\n  call('apiAdminGetDivisions', S.token).then(function(r){\n    if(!r || !r.ok){\n      $('adminContent').innerHTML = '<div class=\"err\">'+esc((r&&r.error)||'Ошибка загрузки оргструктуры')+'</div>';\n      return;\n    }\n    S.adminDivs = r.divisions || [];\n    renderAdminDivisions();\n  }).catch(function(){\n    $('adminContent').innerHTML = '<div class=\"err\">Нет связи с сервером</div>';\n  });\n}\n\nfunction renderAdminDivisions(){\n  var divs = S.adminDivs || [];\n  var search = ($('divSearch') ? $('divSearch').value : '').toLowerCase();\n\n  var filtered = divs.filter(function(d){\n    return !search || d.unit.toLowerCase().indexOf(search) >= 0 || d.dir.toLowerCase().indexOf(search) >= 0 ||\n      d.resp.toLowerCase().indexOf(search) >= 0 || d.hrbp.toLowerCase().indexOf(search) >= 0;\n  });\n\n  var h = '<div class=\"dash-filters\">'+\n    '<input id=\"divSearch\" placeholder=\"🔍 Поиск по отделу, направлению, ответственным…\" value=\"'+esc(search)+'\">'+\n  '</div>';\n\n  h += '<div class=\"sec-title\">Оргструктура подразделений ('+filtered.length+')</div>';\n\n  h += '<div class=\"tblwrap\"><table class=\"dash\">'+\n    '<tr><th>Направление / Отдел</th><th>Руководитель / Ответственный</th><th>HR BP</th><th>Действия</th></tr>'+\n    filtered.map(function(d, idx){\n      return '<tr>'+\n        '<td><b>'+esc(d.unit)+'</b><br><small style=\"color:var(--muted)\">'+esc(d.dir)+'</small></td>'+\n        '<td>'+(d.resp ? esc(d.resp) : (d.head ? esc(d.head) : '<span style=\"color:var(--warn)\">Не назначен</span>'))+'</td>'+\n        '<td>'+(d.hrbp ? esc(d.hrbp) : '<span style=\"color:var(--warn)\">Не назначен</span>')+'</td>'+\n        '<td><button class=\"btn-ghost\" style=\"border:1px solid var(--line);min-height:32px;font-size:12px\" onclick=\"openDivisionModal('+idx+')\">✏️ Назначить</button></td>'+\n      '</tr>';\n    }).join('')+\n  '</table></div>';\n\n  $('adminContent').innerHTML = h;\n  $('divSearch').oninput = renderAdminDivisions;\n}\n\nfunction openDivisionModal(idx){\n  var d = (S.adminDivs || [])[idx];\n  if(!d) return;\n\n  var el = document.createElement('div');\n  el.className = 'sheet';\n  el.innerHTML = '<div class=\"sheet-in\">'+\n    '<div class=\"sheet-hd\"><b>'+esc(d.unit)+'</b>'+\n      '<button class=\"btn-ghost\" data-x=\"1\">Закрыть</button></div>'+\n    '<label class=\"lbl\" style=\"margin-top:4px\">Направление</label>'+\n    '<input id=\"dmDir\" value=\"'+esc(d.dir)+'\">'+\n    '<label class=\"lbl\">Руководитель отдела</label>'+\n    '<input id=\"dmHead\" value=\"'+esc(d.head)+'\">'+\n    '<label class=\"lbl\">Ответственный за обзор</label>'+\n    '<input id=\"dmResp\" value=\"'+esc(d.resp)+'\">'+\n    '<label class=\"lbl\">HR BP</label>'+\n    '<input id=\"dmHrbp\" value=\"'+esc(d.hrbp)+'\">'+\n    '<label class=\"lbl\">Примечание</label>'+\n    '<input id=\"dmNote\" value=\"'+esc(d.note)+'\">'+\n    '<div style=\"height:16px\"></div>'+\n    '<button id=\"dmSave\" class=\"btn-primary\">Сохранить</button>'+\n  '</div>';\n\n  document.body.appendChild(el);\n\n  el.addEventListener('click', function(e){\n    if(e.target === el || e.target.dataset.x) el.remove();\n  });\n\n  el.querySelector('#dmSave').onclick = function(){\n    var payload = {\n      unit: d.unit,\n      dir: el.querySelector('#dmDir').value.trim(),\n      head: el.querySelector('#dmHead').value.trim(),\n      resp: el.querySelector('#dmResp').value.trim(),\n      hrbp: el.querySelector('#dmHrbp').value.trim(),\n      note: el.querySelector('#dmNote').value.trim()\n    };\n    var btn = this;\n    btn.disabled = true; btn.textContent = 'Сохраняем…';\n    call('apiAdminSaveDivision', S.token, payload).then(function(res){\n      btn.disabled = false; btn.textContent = 'Сохранить';\n      if(res && res.ok){\n        el.remove();\n        toast('Подразделение обновлено');\n        loadAdminDivisions();\n      } else {\n        toast((res && res.error) || 'Ошибка');\n      }\n    }).catch(function(){\n      btn.disabled = false; btn.textContent = 'Сохранить';\n      toast('Нет связи');\n    });\n  };\n}\n\n// ─── Вкладка: Период сбора ───\nfunction renderAdminPeriod(){\n  var p = S.data.period || {};\n  var closed = p.state === 'закрыт';\n\n  var h = '<div class=\"card\" style=\"margin-bottom:16px\">'+\n    '<div style=\"font-size:12px;color:var(--muted);font-weight:700;text-transform:uppercase;margin-bottom:6px\">Текущий период сбора</div>'+\n    '<div style=\"font-weight:700;font-size:18px\">'+esc(p.name || 'Обзор рынка')+'</div>'+\n    '<div style=\"font-size:13.5px;color:var(--muted);margin-top:6px\">'+\n      'Статус: <b style=\"color:'+(closed?'var(--no)':'var(--ok)')+'\">'+esc(p.state || 'открыт')+'</b>'+\n      (p.from ? ' · с '+esc(p.from) : '') + (p.to ? ' · по '+esc(p.to) : '') +\n      (p.by ? '<br>Изменил: <b>'+esc(p.by)+'</b>'+(p.at?' ('+esc(p.at)+')':'') : '') +\n    '</div>'+\n    '<div style=\"height:16px\"></div>'+\n    (closed\n      ? '<button id=\"btnAdminPeriodOpen\" class=\"btn-line\" style=\"color:var(--ok);border-color:var(--ok);font-weight:700\">Открыть новый период</button>'\n      : '<button id=\"btnAdminPeriodClose\" class=\"btn-line btn-danger\">Закрыть период сбора</button>')+\n  '</div>';\n\n  $('adminContent').innerHTML = h;\n\n  if($('btnAdminPeriodOpen')){\n    $('btnAdminPeriodOpen').onclick = function(){\n      askText({\n        title: 'Открыть новый период сбора',\n        html: 'Все сотрудники получат доступ к редактированию и внесению данных.',\n        value: 'Обзор рынка — ' + new Date().toLocaleDateString('ru-RU', {month:'long', year:'numeric'}),\n        ok: 'Открыть период'\n      }).then(function(name){\n        if(!name) return;\n        call('apiSetPeriod', S.token, { state:'открыт', name:name }).then(function(res){\n          if(res && res.ok){\n            S.data.period = res.period;\n            toast('Период открыт');\n            renderAdminPeriod();\n          } else {\n            toast((res&&res.error)||'Ошибка');\n          }\n        });\n      });\n    };\n  }\n\n  if($('btnAdminPeriodClose')){\n    $('btnAdminPeriodClose').onclick = function(){\n      ask({\n        title: 'Закрыть период сбора данных?',\n        html: 'Руководители и сотрудники больше не смогут изменять данные (только просмотр).',\n        ok: 'Закрыть период',\n        danger: true\n      }).then(function(yes){\n        if(!yes) return;\n        call('apiSetPeriod', S.token, { state:'закрыт' }).then(function(res){\n          if(res && res.ok){\n            S.data.period = res.period;\n            toast('Период закрыт');\n            renderAdminPeriod();\n          } else {\n            toast((res&&res.error)||'Ошибка');\n          }\n        });\n      });\n    };\n  }\n}\n\n// ─── Вкладка: Сервис и Журнал ───\nfunction renderAdminTools(){\n  var h = '<div class=\"sec-title\">Сервисные утилиты обслуживания</div>'+\n    '<div class=\"kpi-grid\" style=\"grid-template-columns:1fr;margin-bottom:20px\">'+\n      '<div class=\"card\">'+\n        '<div style=\"font-weight:700;font-size:15px\">🧹 Нормализация сегментов и дублей компаний</div>'+\n        '<div style=\"font-size:13px;color:var(--muted);margin:4px 0 10px\">Сверяет лист «Конкуренты» со справочником компаний, удаляет скрытые пробелы, проставляет правильные сегменты и обновляет справочник.</div>'+\n        '<button class=\"btn-line\" onclick=\"runMaintenanceTool(\\'clean_segments\\', \\'Нормализация сегментов\\')\">Запустить нормализацию</button>'+\n      '</div>'+\n      '<div class=\"card\">'+\n        '<div style=\"font-weight:700;font-size:15px\">🔗 Устранение расхождений в связях</div>'+\n        '<div style=\"font-size:13px;color:var(--muted);margin:4px 0 10px\">Находит и восстанавливает потерянные связи между подразделениями и конкурентами.</div>'+\n        '<button class=\"btn-line\" onclick=\"runMaintenanceTool(\\'fix_links\\', \\'Починка связей\\')\">Устранить расхождения</button>'+\n      '</div>'+\n      '<div class=\"card\">'+\n        '<div style=\"font-weight:700;font-size:15px\">⚡ Полный пересчёт статусов заполнения</div>'+\n        '<div style=\"font-size:13px;color:var(--muted);margin:4px 0 10px\">Синхронизирует лист «Статус заполнения» по всем 326 подразделениям.</div>'+\n        '<button class=\"btn-line\" onclick=\"runMaintenanceTool(\\'sync_status\\', \\'Пересчёт статусов\\')\">Пересчитать статусы</button>'+\n      '</div>'+\n    '</div>';\n\n  h += '<div class=\"sec-title\">Журнал последних действий (Audit Log)</div>'+\n    '<div id=\"auditLogBox\"><div class=\"sp\"><i></i> Загрузка журнала…</div></div>';\n\n  $('adminContent').innerHTML = h;\n\n  call('apiAdminGetAuditLog', S.token, 60).then(function(r){\n    if(!r || !r.ok){\n      $('auditLogBox').innerHTML = '<div class=\"err\">'+esc((r&&r.error)||'Не удалось загрузить журнал')+'</div>';\n      return;\n    }\n    var logs = r.logs || [];\n    if(!logs.length){\n      $('auditLogBox').innerHTML = '<div class=\"empty\">Журнал пуст</div>';\n      return;\n    }\n    var logH = '<div class=\"tblwrap\"><table class=\"dash\">'+\n      '<tr><th>Время</th><th>Логин</th><th>Действие</th><th>Детали</th></tr>'+\n      logs.map(function(l){\n        return '<tr>'+\n          '<td style=\"white-space:nowrap;font-size:12px;color:var(--muted)\">'+esc(l.dt)+'</td>'+\n          '<td><b>'+esc(l.login)+'</b></td>'+\n          '<td>'+esc(l.action)+'</td>'+\n          '<td style=\"font-size:12.5px;color:var(--muted)\">'+esc(l.detail)+'</td>'+\n        '</tr>';\n      }).join('')+\n      '</table></div>';\n    $('auditLogBox').innerHTML = logH;\n  });\n}\n\nfunction runMaintenanceTool(type, title){\n  ask({\n    title: 'Запустить процедуру: ' + title + '?',\n    html: 'Операция выполнится на сервере Google Apps Script и зафиксируется в журнале.',\n    ok: 'Запустить'\n  }).then(function(yes){\n    if(!yes) return;\n    toast('Выполняется: ' + title + '…');\n    call('apiAdminRunMaintenance', S.token, type).then(function(res){\n      if(res && res.ok){\n        ask({ title:'Готово', html: esc(res.message), ok:'Понятно' });\n        renderAdminTools();\n      } else {\n        toast((res && res.error) || 'Ошибка выполнения');\n      }\n    }).catch(function(){\n      toast('Нет связи');\n    });\n  });\n}\n\n// ═══════════════════════════════════════════════════════════\n// СВОДКА ПО HR BP (быстрый вид)\n// ═══════════════════════════════════════════════════════════\nfunction openDash(){\n  setTop('Сводка по подразделениям', userLabel(), true);\n  $('bar').classList.add('hidden');\n  $('body').onclick = null;\n  $('body').innerHTML = '<div class=\"sp\"><i></i> Считаем…</div>';\n  call('apiDashboard', S.token).then(function(r){\n    if(!r || !r.ok){ $('body').innerHTML = '<div class=\"err\">'+esc((r&&r.error)||'Ошибка')+'</div>'; return; }\n    if(r.period) S.data.period = r.period;\n    var p = S.data.period || {};\n    var closed = p.state === 'закрыт';\n\n    var h = '<div class=\"card\" style=\"margin-bottom:16px\">'+\n      '<div style=\"font-size:12.5px;color:var(--muted);font-weight:700;text-transform:uppercase;'+\n        'letter-spacing:.6px;margin-bottom:6px\">Период заполнения</div>'+\n      '<div style=\"font-weight:600;font-size:16px\">'+esc(p.name || 'без названия')+'</div>'+\n      '<div style=\"font-size:13px;color:var(--muted);margin-top:4px\">'+\n        'Состояние: <b style=\"color:'+(closed?'var(--no)':'var(--ok)')+'\">'+esc(p.state||'открыт')+'</b>'+\n        (p.from ? ' · с '+esc(p.from) : '') + (p.to ? ' · по '+esc(p.to) : '') +\n        (p.by ? '<br>изменил: '+esc(p.by)+(p.at?' ('+esc(p.at)+')':'') : '') + '</div>'+\n      '<div style=\"height:12px\"></div>'+\n      (closed\n        ? '<button id=\"btnPeriod\" class=\"btn-line\" style=\"color:var(--ok);border-color:var(--ok)\">Открыть новый период</button>'\n        : '<button id=\"btnPeriod\" class=\"btn-line btn-danger\">Закрыть период заполнения</button>')+\n      '</div>';\n\n    var done = r.rows.filter(function(x){ return x.total && x.done === x.total; }).length;\n    var svTotal = r.rows.reduce(function(s,x){ return s + (x.surveys||0); }, 0);\n    var askTotal = r.rows.reduce(function(s,x){ return s + (x.ask||0); }, 0);\n    h += '<div class=\"sec-title\">Заполнено полностью: '+done+' из '+r.rows.length+\n         ' · записей по должностям: '+svTotal+'</div>';\n    if(askTotal){\n      h += '<div class=\"note\">На уточнении по всем подразделениям: <b>'+askTotal+'</b> компаний. '+\n           'Они не входят в «проверено».</div>';\n    }\n    h += '<div class=\"tblwrap\"><table class=\"dash\">'+\n      '<tr><th>Подразделение</th><th>Ответственный</th><th>Компании</th><th>Уточнить</th>'+\n      '<th>Данные</th><th>Обновлено</th></tr>';\n    h += r.rows.map(function(x){\n      var pct = x.total ? Math.round(x.done/x.total*100) : 0;\n      var cls = pct>=100 ? 'p-ok' : (pct>0 ? 'p-mid' : 'p-no');\n      var scls = x.surveys>0 ? 'p-ok' : 'p-no';\n      return '<tr><td>'+esc(x.unit)+'</td><td>'+esc(x.resp)+'</td>'+\n        '<td><span class=\"pill '+cls+'\">'+x.done+'/'+x.total+'</span></td>'+\n        '<td>'+((x.ask||0) ? '<span class=\"pill p-ask\">'+x.ask+'</span>' : '—')+'</td>'+\n        '<td><span class=\"pill '+scls+'\">'+(x.surveys||0)+'</span></td>'+\n        '<td style=\"font-size:12px;color:var(--muted)\">'+esc(x.at||'—')+'</td></tr>';\n    }).join('');\n    h += '</table></div>';\n    $('body').innerHTML = h;\n\n    $('btnPeriod').onclick = function(){\n      var btn = this;\n      if(closed){\n        askText({\n          title: 'Открыть новый период',\n          html: 'Руководители снова смогут вносить и удалять данные.',\n          value: 'Обзор рынка — ' +\n            new Date().toLocaleDateString('ru-RU', {month:'long', year:'numeric'}),\n          placeholder: 'Название периода',\n          ok: 'Открыть период'\n        }).then(function(name){\n          if(name === null) return;\n          btn.disabled = true; btn.textContent = 'Открываем…';\n          call('apiSetPeriod', S.token, { state:'открыт', name:name })\n            .then(afterPeriod).catch(periodFail);\n        });\n      } else {\n        ask({\n          title: 'Закрыть период заполнения?',\n          html: 'Руководители перейдут в режим просмотра — вносить и удалять данные ' +\n                'они больше не смогут.\\nВы как HR BP сможете править и после закрытия.',\n          ok: 'Закрыть период',\n          danger: true\n        }).then(function(yes){\n          if(!yes) return;\n          btn.disabled = true; btn.textContent = 'Закрываем…';\n          call('apiSetPeriod', S.token, { state:'закрыт' }).then(afterPeriod).catch(periodFail);\n        });\n      }\n    };\n    function afterPeriod(res){\n      if(!res || !res.ok){ toast((res&&res.error)||'Не удалось изменить период'); openDash(); return; }\n      S.data.period = res.period;\n      var isElevated = (S.data.user.role === 'admin' || S.data.user.role === 'cb');\n      S.ro = !!(res.period.state === 'закрыт' && S.data.user.role !== 'hrbp' && !isElevated);\n      toast('Период ' + res.period.state);\n      openDash();\n    }\n    function periodFail(){ toast('Нет связи'); openDash(); }\n  });\n}\n</script>\n\n</body>\n</html>";